INSERT INTO "public"."toc_rows" ("id", "toc_file_id", "row_number", "day_label", "topic", "data") OVERRIDING SYSTEM VALUE VALUES
	(1, 1, 3, NULL, 'Pre-Assessment (Prerequisites)', '{"Week": "Pre-Program", "Topic": "Pre-Assessment (Prerequisites)", "Module": "Prerequisite Validation", "Sub Topic": "REST APIs / HTTP concepts, service-layer thinking\nVersion control, pipelines, build/deploy/artifacts\nStructure, styling, basic layout\nSyntax, functions, arrays/objects\nTest basics, breakpoint/log-based debugging\nArrays, objects, basic algorithms\nRequest/response shapes, manual API testing", "Duration (Hrs)": "1.5"}'),
	(2, 1, 4, NULL, 'Trainer-Led Orientation', '{"Week": "Pre-Program", "Topic": "Trainer-Led Orientation", "Module": "Program Orientation", "Sub Topic": "Program kickoff led by the Trainer: introduce the PulseCart OneJourney case study and the 32-session journey, walk through the curriculum structure, Milestone/Interview Bot/Capstone checkpoints, tooling and environment setup, and readiness/scoring criteria; address learner questions before Day 1 begins.", "Hands-on Labs": "Environment/tooling access confirmed + orientation attendance record.", "Duration (Hrs)": "2", "Learning Outcomes": "Learners understand the program structure, tooling access is verified, and expectations/readiness criteria are clear before Day 1.", "Learning Type (SPL / IL)": "IL"}'),
	(3, 1, 6, 'Day 1', 'Spring Boot Fundamentals, REST Controllers, Dependency Injection', '{"Day": "Day 1", "Week": "Week 1", "Topic": "Spring Boot Fundamentals, REST Controllers, Dependency Injection", "Module": "Java Backend Development", "Source": "PACKT", "Remarks": "Include Modules\nIntroduction to Spring Boot in 14 Steps - 1h 13m\nRESTful Web Services with Spring and Spring Boot - 3h 20m\nfrom given course", "Duration": "4:33:00", "Sub Topic": "Spring Boot project structure, auto-configuration and starter dependencies\nSpring IoC container and dependency injection with @Component/@Service/@Repository/@Autowired\nBuilding REST controllers with @RestController, request mapping and path/query parameters\nRequest/response JSON serialization with Jackson\nLayered architecture: Controller-Service-Repository pattern\nConfiguration management with application.properties/yml and profiles\nException handling with @ControllerAdvice and custom error responses\nRunning and debugging a Spring Boot application locally Delivered as an Instructor-Led (IL) session because of its complexity, integration or coordination needs; the mentor also opens with a guided review of the preceding Self-Paced (SPL) day(s) and resolves learner queries from those days before moving into today''s live topic.", "Proficiency": "Advanced", "Hands-on Labs": "Case Study – Spring Boot Fundamentals, REST Controllers, Dependency Injection\nInput: PulseCart backend requirements, the agreed data model and existing project baseline.\nImplement: Stand up a layered Spring Boot service and expose the PulseCart catalog endpoints using controllers, services and dependency injection.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant integration path.\nOutput: Working Spring Boot Fundamentals, REST Controllers, Dependency Injection increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "4", "Published Date": "3/31/23", "Total Duration": "4:33:00", "Course / You tube": "Master Java Web Services and REST API with Spring Boot[Updated]", "Learning Outcomes": "Stand up a layered Spring Boot REST service and expose PulseCart catalog endpoints using controllers, services and dependency injection.", "Learning Type (SPL / IL)": "IL", "Customised course names for Skill Assist": "Master Java Web Services and REST API with Spring Boot[Updated] 1 - Sony Java with Angular"}'),
	(4, 1, 7, 'Day 2', 'Relational Database Design & JPA Entity Modeling', '{"Day": "Day 2", "Week": "Week 1", "Topic": "Relational Database Design & JPA Entity Modeling", "Module": "Java Backend Development", "Source": "PACKT", "Remarks": "Include Modules\nJPA and Hibernate in Depth - 2h 3m\nEstablishing Relationships with JPA and Hibernate - OneToMany and ManyToMany - 1h 15m\nHibernate & JPA Tips - 36m\nfrom given course", "Duration": "3:54:00", "Sub Topic": "Relational database design fundamentals: tables, primary/foreign keys, normalization\nDesigning the catalog/cart/order schema for PulseCart (ERD-level thinking)\nJPA annotations for entity modeling (@Entity, @Id, @GeneratedValue, @Column)\nMapping one-to-many and many-to-many relationships between entities\nEmbeddable types and value objects for reusable field groups\nChoosing appropriate column types, constraints and indexes\nAuditing fields (created/updated timestamps) and soft-delete patterns\nReviewing the schema against expected query patterns before implementation", "Proficiency": "Advanced", "Hands-on Labs": "Case Study – Relational Database Design & JPA Entity Modeling\nInput: PulseCart backend requirements, the agreed data model and existing project baseline.\nImplement: Design the relational schema for the PulseCart catalog/cart/order domain and model it as JPA entities with correct relationships.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant integration path.\nOutput: Working Relational Database Design & JPA Entity Modeling increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "4", "Published Date": "3/23/18", "Total Duration": "3:54:00", "Course / You tube": "Master Hibernate and JPA with Spring Boot in 100 Step.", "Learning Outcomes": "Design a normalized relational schema and model it correctly as JPA entities for the PulseCart domain.", "Learning Type (SPL / IL)": "SPL", "Customised course names for Skill Assist": "Master Hibernate and JPA with Spring Boot in 100 Step 1 - Sony Java with Angular"}'),
	(5, 1, 8, 'Day 3', 'Spring Data JPA Repositories, Queries & Transactions', '{"Day": "Day 3", "Week": "Week 1", "Topic": "Spring Data JPA Repositories, Queries & Transactions", "Module": "Java Backend Development", "Source": "PACKT", "Remarks": "Include Modules\nQueries with Entities using JPQL - 24m\nQueries using Java API - Criteria Queries -18m\nTransaction Management - 34m\nSpring Data JPA & Spring Data REST - 36m\nPerformance Tuning Tips with Hibernate & JPA - 17m\nfrom given course", "Duration": "2:09:00", "Sub Topic": "Spring Data JPA repositories and derived query methods\nCustom queries with JPQL and native @Query\nTransactions and @Transactional boundaries; propagation and isolation basics\nDatabase migrations with Flyway/Liquibase basics\nPagination and sorting for list endpoints\nMapping entities to DTOs for clean API contracts\nN+1 query detection and fetch-strategy tuning (lazy vs eager)\nValidating repository behavior against the PulseCart requirements", "Proficiency": "Advanced", "Hands-on Labs": "Case Study – Spring Data JPA Repositories, Queries & Transactions\nInput: PulseCart backend requirements, the agreed data model and existing project baseline.\nImplement: Implement Spring Data JPA repositories, custom queries and migrations for the PulseCart catalog/cart/order domain, then expose paginated, DTO-mapped data.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant integration path.\nOutput: Working Spring Data JPA Repositories, Queries & Transactions increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "4", "Published Date": "3/23/18", "Total Duration": "2:09:00", "Course / You tube": "Master Hibernate and JPA with Spring Boot in 100 Step.", "