	(17, 1, 26, 'Day 15', 'Angular Routing & Navigation', '{"Day": "Day 15", "Week": "Week 3", "Topic": "Angular Routing & Navigation", "Module": "Angular Frontend Development", "Source": "RADO", "Remarks": "Include module\nRoutes and Navigation - 1hr 39m\nfrom given course", "Duration": "1:39:00", "Sub Topic": "Angular Router configuration, route parameters and navigation\nNested/child routes and route guards for protected navigation\nLazy-loaded feature routes for scalable applications\nProgrammatic navigation and query-parameter handling\nRoute resolvers for pre-fetching data before navigation\nHandling 404/invalid-route states gracefully\nBuilding the PulseCart catalog → product → cart → checkout route flow\nTesting navigation continuity across the full route flow", "Proficiency": "Advanced", "Hands-on Labs": "Case Study – Angular Routing & Navigation\nInput: PulseCart frontend requirements, the finalized Java REST contract and existing project baseline.\nImplement: Add routes for catalog, product, cart and sign-in, including a lazy-loaded feature module and route guards.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant integration path.\nOutput: Working Angular Routing & Navigation increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "4", "Published Date": "4/14/23", "Total Duration": "1:39:00", "Course / You tube": "Angular 15", "Learning Outcomes": "Build a complete, guarded Angular route flow from catalog to checkout.", "Learning Type (SPL / IL)": "SPL", "Customised course names for Skill Assist": "Angular 15 - Sony Java with Angular 2"}'),
	(18, 1, 27, 'Day 16', 'Forms — Template-driven & Reactive, Validation', '{"Day": "Day 16", "Week": "Week 4", "Topic": "Forms — Template-driven & Reactive, Validation", "Module": "Angular Frontend Development", "Source": "PACKT", "Remarks": "Include modules\nAngular Template Driven Forms - 16m\nAngular Reactive Forms - 53m\nCustom Form Validators - 11m\neStore Project - 5hr 15m\nfrom given course", "Duration": "6:53:00", "Sub Topic": "Template-driven forms with ngModel and form directives\nReactive forms: FormGroup, FormControl and FormBuilder for complex forms\nField-level, form-level and cross-field validation using built-in and custom validators\nValidation messages, submission states and user feedback\nHandling invalid form states safely without breaking the user journey\nChoosing template-driven vs reactive forms for a given use case\nBuilding the PulseCart delivery-preference form with both approaches\nTesting validation rules against valid and invalid input", "Proficiency": "Advanced", "Hands-on Labs": "Case Study – Forms — Template-driven & Reactive, Validation\nInput: PulseCart frontend requirements, the finalized Java REST contract and existing project baseline.\nImplement: Implement the delivery-preference form using both template-driven and reactive approaches with validation.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant integration path.\nOutput: Working Forms — Template-driven & Reactive, Validation increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "4", "Published Date": "10/21/24", "Total Duration": "6:53:00", "Course / You tube": "Mastering Angular with Interview Preparation and E-commerce App", "Learning Outcomes": "Build validated Angular forms using both template-driven and reactive approaches.", "Learning Type (SPL / IL)": "SPL", "Customised course names for Skill Assist": "Mastering Angular with Interview Preparation and E-commerce App 1 - Sony Java with Angular"}'),
	(23, 1, 32, 'Day 21', 'Angular Application Consolidation & End-to-End Integration Review', '{"Day": "Day 21", "Week": "Week 5", "Topic": "Angular Application Consolidation & End-to-End Integration Review", "Module": "Angular Frontend Development", "Source": "PACKT", "Duration": "5:42:00", "Sub Topic": "Component decomposition for complete business journeys rather than isolated widgets\nReusable page shells, cards, forms, feedback and loading/error components\nConsuming the full Java Spring Boot REST API end-to-end from the Angular client\nShared-service state vs component-local state across catalog, cart and account flows\nReusable custom directives/pipes for common UI/session behaviors\nConsistent responsive behavior across the complete web journey\nAccessibility-aware component structure and keyboard-friendly interactions\nIntegration of routing, forms, state, HttpClient and reusable components into one cohesive Angular experience", "Proficiency": "Intermediate", "Hands-on Labs": "Case Study – Angular Frontend Journey Consolidation\nInput: Existing PulseCart catalog, product, cart and account pages plus the finalized Java REST contract from prior sessions.\nImplement: Refactor the journey into reusable components and services; standardize state ownership and responsive behavior.\nIntegrate: Combine routing, forms, shared state and HttpClient calls into one cohesive Angular journey fully wired to the Spring Boot backend.\nValidate: Verify desktop/tablet/mobile behavior, navigation continuity, state preservation and end-to-end API integration.\nOutput: Consolidated Angular frontend fully integrated with the Java Spring Boot backend.\nEvidence: Source code, screenshots across breakpoints, component map and short implementation note.", "Duration (Hrs)": "4", "Published Date": "5/31/19", "Total Duration": "5:42:00", "Course / You tube": "Architecting Reactive Angular Applications with Redux and NgRx", "Learning Outcomes": "Consolidate a complete Angular frontend journey fully integrated with the Java Spring Boot backend.", "Learning Type (SPL / IL)": "SPL"}'),
	(19, 1, 28, 'Day 17', 'State Management — Services, RxJS & NgRx', '{"Day": "Day 17", "Week": "Week 4", "Topic": "State Management — Services, RxJS & NgRx", "Module": "Angular Frontend Development", "Source": "PACKT", "Duration": "6:59:00", "Sub Topic": "When a shared service with RxJS is enough vs when a store (NgRx) is required\nAngular services and dependency injection for shared state\nRxJS Observables, Subjects and BehaviorSubjects for reactive state\nNgRx store, actions, reducers and effects for predictable state management\nSelectors and predictable read access to shared state\nManaging session, cart and preference state across multiple screens\nUpdating normalized/shared state without uncontrolled mutation\nChoosing Services/RxJS vs NgRx based on application complexity Delivered as an Instructor-Led (IL) session because of its complexity, integration or coordination needs; the mentor also opens with a guided review of the preceding Self-Paced (SPL) day(s) and resolves learner queries from those days before moving into today''s live topic.", "Proficiency": "Advanced", "Hands-on Labs": "Case Study – State Management — Services, RxJS & NgRx\nInput: PulseCart frontend requirements, the finalized Java REST contract and existing project baseline.\nImplement: Centralize cart, session and preference state using a shared service/RxJS approach, then migrate the most complex slice to NgRx.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant integration path.\nOutput: Working State Management — Services, RxJS & NgRx increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "4", "Published Date": "12/17/25", "Total Duration": "6:59:00", "Course / You tube": "Angular and NgRx Developer Lab 2026 - Build a Real Application", "Learning Outcomes": "Manage cross-page application state predictably using Angular services, RxJS or NgRx.", "Learning Type (SPL / IL)": "IL"}'),
	(20, 1, 29, 'Day 18', 'HttpClient API Integration with the Spring Boot Backend', '{"Day": "Day 18", "Week": "Week 4", "Topic": "HttpClient API Integration with the Spring Boot Backend", "Module": "Angular Frontend Development", "Source": "PACKT\nRADO", "Remarks": "Include modules\nConnecting RESTful Web Service to JPA - 1hr 18m\nRESTful Web Services - Best Practices - 6m\nfrom Master Java Web Services and REST API with Spring Boot[Updated] course\n\nInclude modules\nHTTP and Observables - 1hr 19m\nServices and Dependency Injection - 57m\nfrom Angular 15 course", "Duration": "1:24:00 \n2:16:00", "Sub Topic": "Creating a reusable Angular HttpClient service layer to consume the Spring Boot REST API\nRequest payload construction and response mapping with RxJS operators\nLoading, success, empty and error-state orchestration\nHandling 4xx/5xx responses and mapping them to user-friendly messages\nRetry/retry-safe interaction patterns using RxJS retry operators\nKeeping API contracts aligned with the backend DTO models\nConnecting catalog, account and order screens to live Spring Boot endpoints\nVerifying request/response shapes against the published OpenAPI contract", "Proficiency": "Advanced\nAdvanced", "Hands-on Labs": "Case Study – HttpClient API Integration with the Spring Boot Backend\nInput: PulseCart frontend requirements, the finalized Java REST contract and existing project baseline.\nImplement: Connect the PulseCart catalog, account and order screens to the Spring Boot backend via a reusable HttpClient service layer.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant integration path.\nOutput: Working HttpClient API Integration with the Spring Boot Backend increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "4", "Published Date": "3/31/2023\n4/14/2023", "Total Duration": "3:40:00", "Course / You tube": "Master Java Web Services and REST API with Spring Boot[Updated]\nAngular 15", "Learning Outcomes": "Integrate the Angular client end-to-end with the Java Spring Boot REST API.", "Learning Type (SPL / IL)": "SPL", "Customised course names for Skill Assist": "Master Java Web Services and REST API with Spring Boot[Updated] 2 - Sony Java with Angular\nAngular 15 - Sony Java with Angular 3"}'),
	(21, 1, 30, 'Day 19', 'Error Handling, HTTP Interceptors, Auth Integration (JWT)', '{"Day": "Day 19", "Week": "Week 4", "Topic": "Error Handling, HTTP Interceptors, Auth Integration (JWT)", "Module": "Angular Frontend Development", "Source": "PACKT", "Remarks": "Include modules\nRoute Guards - 42m\nRxJS Operators - 47m\nObservables & RxJS - 31m\nHandling HTTP Calls With Angular - 47m\nAngular Routing - 54m\nfrom given course", "Duration": "3:41:00", "Sub Topic": "HTTP interceptors for auth headers and centralized error normalization\nPropagating JWT tokens issued by the Spring Boot backend to protected API calls\nLoading, success, empty and error-state orchestration\nHandling 4xx/5xx responses and user-friendly error messages\nRetry/retry-safe interaction patterns using RxJS retry operators\nHandling token expiry/authorization failures without corrupting UI state\nRoute guards for protected Angular routes\nKeeping API contracts aligned with the backend DTO models", "Proficiency": "Advanced", "Hands-on Labs": "Case Study – Error Handling, HTTP Interceptors, Auth Integration (JWT)\nInput: PulseCart frontend requirements, the finalized Java REST contract and existing project baseline.\nImplement: Connect catalog, authentication and order APIs; propagate JWTs via an interceptor and surface field, authorization and server errors without breaking journeys.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant integration path.\nOutput: Working Error Handling, HTTP Interceptors, Auth Integration (JWT) increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "4", "Published Date": "10/21/24", "Total Duration": "3:41:00", "Course / You tube": "Mastering Angular with Interview Preparation and E-commerce App", "Learning Outcomes": "Integrate Angular with the secured Spring Boot backend, handling JWT auth and resilient error states.", "Learning Type (SPL / IL)": "SPL", "Customised course names for Skill Assist": "Mastering Angular with Interview Preparation and E-commerce App 2 - Sony Java with Angular"}'),
	(22, 1, 31, 'Day 20', 'Performance Optimization, Change Detection, Lazy Loading', '{"Day": "Day 20", "Week": "Week 4", "Topic": "Performance Optimization, Change Detection, Lazy Loading", "Module": "Angular Frontend Development", "Source": "PACKT\nRADO", "Remarks": "Include modules\nComponent Life Cycle - Lifecycle Hooks - 45m\nAngular Pipes - 31m\nLazy Loading - 47m\nSignals - Angular 16 - 38m\nfrom Mastering Angular with Interview Preparation and E-commerce App course\n\nInclude module\nAngular Change Detection - 50m\nfrom Angular 15 course", "Duration": "2:41:00 \n0:50:00", "Sub Topic": "Understanding Angular''s change detection strategy and common bottlenecks\nOnPush change detection and immutable data patterns\nDetecting unnecessary re-renders and expensive computations\nPure pipes and memoization-style optimization techniques\nLazy loading feature modules and routes\nPreloading strategies and reducing initial bundle size\ntrackBy functions for efficient list rendering\nValidating performance improvements without introducing stale state or logic defects Delivered as an Instructor-Led (IL) session because of its complexity, integration or coordination needs; the mentor also opens with a guided review of the preceding Self-Paced (SPL) day(s) and resolves learner queries from those days before moving into today''s live topic.", "Proficiency": "Advanced\nAdvanced", "Hands-on Labs": "Case Study – Performance Optimization, Change Detection, Lazy Loading\nInput: PulseCart frontend requirements, the finalized Java REST contract and existing project baseline.\nImplement: Lazy-load lower-frequency routes and reduce avoidable re-renders in catalog/cart screens; capture before/after evidence.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant integration path.\nOutput: Working Performance Optimization, Change Detection, Lazy Loading increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "4", "Published Date": "10/21/2024\n4/14/2023", "Total Duration": "3:31:00", "Course / You tube": "Mastering Angular with Interview Preparation and E-commerce App\nAngular 15", "Learning Outcomes": "Improve Angular runtime and loading performance using change-detection and lazy-loading techniques.", "Learning Type (SPL / IL)": "IL", "Customised course names for Skill Assist": "Mastering Angular with Interview Preparation and E-commerce App 3- Sony Java with Angular\nAngular 15 - Sony Java with Angular 4"}'),
	(39, 2, 10, 'Day 3', 'Architecture Decision Records & Review Practice', '{"Day": "Day 3", "Week": "Week 1", "Topic": "Architecture Decision Records & Review Practice", "Module": "Data Architecture Foundations & Practice", "Sub Topic": "Participants learn how to document and communicate the reasoning behind a data architecture decision using an industry-standard format called an Architecture Decision Record (ADR), so anyone joining the project later can understand why a choice was made without having to ask around. The session also covers how to run a structured peer design review -- similar to a code review, but for architecture -- so decisions are challenged and validated by others before they are locked in, rather than approved informally.", "Learning Type": "SPL", "Duration (Hrs)": "2", "Hands-on Activity": "Formalize the pattern decision from Session 1 as an Architecture Decision Record, then run a structured peer review of the data NFRs defined in Session 2 and log the review outcomes.", "Learning Outcomes": "ADR-001 and a peer-review log added to the Meridian Financial Group architecture package."}'),
	(24, 1, 36, 'Day 22', 'Backend + Frontend Integration', '{"Day": "Day 22", "Week": "Week 5", "Topic": "Backend + Frontend Integration", "Module": "Full Stack Engineering", "Source": "PACKT", "Duration": "7:36:00", "Sub Topic": "Aligning the Angular client with the Java Spring Boot REST contract built in Module 1\nTracing request/response flow from Spring Boot controllers through to Angular components\nDTO/payload mapping and validation at integration boundaries\nConsistent error contracts and client-side interpretation\nHandling version/contract mismatches without silent failures\nCross-origin/environment configuration considerations for local and deployed environments\nCoordinating shared endpoints consumed by the Angular client\nTroubleshooting end-to-end integration with logs, network traces and API-test evidence", "Proficiency": "Intermediate", "Hands-on Labs": "Case Study – Backend + Frontend Integration\nInput: PulseCart backend requirements, the agreed data model and existing project baseline.\nImplement: Trace an order-status request from the Java Spring Boot backend through the Angular client, including request/response mapping.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant integration path.\nOutput: Working Backend + Frontend Integration increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "5", "Published Date": "6/19/18", "Total Duration": "7:36:00", "Course / You tube": "Fullstack Web Development with Angular and Spring", "Learning Outcomes": "Own an end-to-end integration flow across the Java Spring Boot backend and the Angular client.", "Learning Type (SPL / IL)": "SPL"}'),
	(25, 1, 37, 'Day 23', 'Authentication, Authorization (JWT, OAuth)', '{"Day": "Day 23", "Week": "Week 5", "Topic": "Authentication, Authorization (JWT, OAuth)", "Module": "Full Stack Engineering", "Source": "PACKT", "Remarks": "Include modules\nSpring Security Java Configuration - 18m\nUser Authorities - 36m\nMulti-tenancy Security - 1hr 11m\nCross-Site Request Forgery (CSRF) Protection with Spring Security - 17m\nfrom Spring Security Core: Beginner to Guru course", "Duration": "2:22:00", "Sub Topic": "Backend Day 5-6 built JWT issuance and role-based authorization in isolation; this session validates that security end-to-end across the live, integrated system rather than re-teaching the mechanics\nEnd-to-end session lifecycle: login, token storage, silent refresh, expiry and forced logout across Angular and Spring Boot\nVerifying interceptor-based token propagation survives page reloads, route changes and concurrent tab sessions\nCross-layer authorization drift: catching cases where the UI hides an action but the API still allows it (and vice versa)\nOAuth delegated-authorization walkthrough for a third-party integration scenario (e.g. social sign-in)\nSession-fixation, token-replay and CSRF considerations at the integration boundary\nLightweight threat modeling for the authenticated order/account flows as a whole system\nPenetration-style manual testing of the auth boundary: tampered tokens, expired sessions, role escalation attempts", "Proficiency": "Intermediate", "Hands-on Labs": "Case Study – Cross-Layer Security & Session Validation\nInput: The fully integrated PulseCart Angular + Spring Boot application with authentication already implemented on both layers.\nImplement: Exercise the complete login-to-logout session lifecycle across both layers; attempt token tampering, expired-session and role-escalation scenarios and confirm the system rejects each one correctly.\nIntegrate: Treat frontend and backend as one security boundary rather than testing either layer in isolation.\nValidate: Produce a short threat-model note and a table of attack attempts vs. observed system response.\nOutput: A signed-off cross-layer security validation covering session lifecycle, token handling and authorization drift.\nEvidence: Threat-model note, attack-attempt/response table, screenshots or logs of each blocked scenario.", "Duration (Hrs)": "3", "Published Date": "9/30/20", "Total Duration": "2:22:00", "Course / You tube": "Spring Security Core: Beginner to Guru", "Learning Outcomes": "Validate authentication and authorization as one end-to-end system property, not two separately-tested layers.", "Learning Type (SPL / IL)": "SPL", "Customised course names for Skill Assist": "Spring Security Core: Beginner to Guru - Sony Java with Angular"}'),
	(26, 1, 38, 'Day 24', 'Testing (Unit, Integration, E2E basics)', '{"Day": "Day 24", "Week": "Week 6", "Topic": "Testing (Unit, Integration, E2E basics)", "Module": "Full Stack Engineering", "Source": "PACKT\nPACKT", "Duration": "3:36:00 \n3:55:00", "Sub Topic": "Testing pyramid and responsibility across frontend/backend/full-stack layers\nUnit testing reusable functions and business logic\nAngular component testing with Jasmine and Karma\nSpring Boot service/controller testing with JUnit and Mockito\nMocking dependencies and API interactions on both layers\nCoordinating Spring Boot and Angular test suites for one end-to-end feature\nPositive, negative, boundary and failure-path coverage\nDesigning tests that are deterministic, maintainable and useful in CI/CD", "Proficiency": "Advanced\nIntermediate", "Hands-on Labs": "Case Study – Testing (Unit, Integration, E2E basics)\nInput: PulseCart backend requirements, the agreed data model and existing project baseline.\nImplement: Create tests for reusable UI logic, API-integrated screens and one critical user flow from sign-in to order status.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant integration path.\nOutput: Working Testing (Unit, Integration, E2E basics) increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "3", "Published Date": "12/18/2025\n5/25/2018", "Total Duration": "7:31:00", "Course / You tube": "Angular Testing Masterclass 2026 - Unit and E2E Test Essentials\nMaster Java Unit Testing with Spring Boot and Mockito", "Learning Outcomes": "Design and execute layered tests that protect critical full-stack behavior.", "Learning Type (SPL / IL)": "SPL"}'),
	(27, 1, 39, 'Day 25', 'CI/CD, Observability, Logging', '{"Day": "Day 25", "Week": "Week 6", "Topic": "CI/CD, Observability, Logging", "Module": "Full Stack Engineering", "Source": "PACKT\nPACKT", "Duration": "3:16:00 \n3:07:00", "Sub Topic": "CI/CD lifecycle from commit to build, test and deploy\nAutomating lint/build/test quality gates for both layers\nEnvironment-specific configuration and deployment variables\nPackaging/deploying the Java Spring Boot backend and the Angular frontend and coordinating release workflow\nStructured client/integration logging for troubleshooting\nCorrelation identifiers and traceable request journeys where applicable\nBasic observability signals for failures and user-impacting issues\nUsing deployment and operational evidence to validate production readiness", "Proficiency": "Intermediate\nIntermediate", "Hands-on Labs": "Case Study – CI/CD, Observability, Logging\nInput: PulseCart backend requirements, the agreed data model and existing project baseline.\nImplement: Define and exercise a pipeline path that runs checks and deploys the backend/frontend deliverables; add correlation-friendly logging.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant integration path.\nOutput: Working CI/CD, Observability, Logging increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "5", "Published Date": "7/27/2018\n2/27/2023", "Total Duration": "6:23:00", "Course / You tube": "Application Development with Spring 5.0 and Angular 6\nLearning GitHub Actions for DevOps CI/CD", "Learning Outcomes": "Connect quality gates, deployment automation and observability to the delivery lifecycle.", "Learning Type (SPL / IL)": "SPL"}'),
	(28, 1, 40, 'Day 26', 'Secure Coding Practices', '{"Day": "Day 26", "Week": "Week 6", "Topic": "Secure Coding Practices", "Module": "Full Stack Engineering", "Source": "PACKT", "Duration": "3:06:00", "Sub Topic": "Input and output validation at client/integration boundaries\nPreventing unsafe rendering and injection-style vulnerabilities (SQL injection, XSS)\nSafe handling of tokens, secrets and sensitive application data\nAvoiding insecure storage of sensitive information on either layer\nDependency hygiene and awareness of vulnerable packages\nSecure error handling without exposing internal details\nAuthorization-aware UI and API behavior and defensive coding\nSecurity review checklist applied to the Java Spring Boot backend and the Angular frontend Delivered as an Instructor-Led (IL) session because of its complexity, integration or coordination needs; the mentor also opens with a guided review of the preceding Self-Paced (SPL) day(s) and resolves learner queries from those days before moving into today''s live topic.", "Proficiency": "Advanced", "Hands-on Labs": "Case Study – Secure Coding Practices\nInput: PulseCart backend requirements, the agreed data model and existing project baseline.\nImplement: Review PulseCart''s Spring Boot and Angular code for insecure storage, overexposed errors and unsafe input handling; remediate findings.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant integration path.\nOutput: Working Secure Coding Practices increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "4", "Published Date": "12/23/22", "Total Duration": "3:06:00", "Course / You tube": "A Detailed Guide to the OWASP Top 10 [Updated 2026]", "Learning Outcomes": "Apply secure coding practices across the Java Spring Boot backend, the Angular frontend and their integration boundaries.", "Learning Type (SPL / IL)": "IL"}'),
	(29, 1, 41, 'Day 27', 'AI-Assisted Development Tools', '{"Day": "Day 27", "Week": "Week 6", "Topic": "AI-Assisted Development Tools", "Module": "Full Stack Engineering", "Source": "RADO\nPACKT", "Duration": "0:33:00 \n5:58:00", "Sub Topic": "Using AI-assisted development for code explanation and unfamiliar-code navigation\nGenerating candidate tests and edge cases from existing implementation\nRefactoring suggestions with developer-controlled acceptance\nPrompting with precise technical context and constraints\nVerifying generated code for correctness, security and maintainability\nAvoiding sensitive-data leakage into non-approved AI tools\nRecording accepted/rejected suggestions and engineering rationale\nTreating AI output as an accelerator, not as an unverified source of truth", "Proficiency": "Basic\nIntermediate", "Hands-on Labs": "Case Study – AI-Assisted Development Tools\nInput: PulseCart backend requirements, the agreed data model and existing project baseline.\nImplement: Use a client-approved AI assistant to propose a refactor/test set, verify every change and record accepted/rejected suggestions.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant integration path.\nOutput: Working AI-Assisted Development Tools increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "5", "Published Date": "6/26/2023\n2/14/2025", "Total Duration": "6:31:00", "Course / You tube": "GitHub Copilot: AI-Powered Code Generation\nWriting Clean Code - 20 Common Code Smells and How to Avoid Them", "Learning Outcomes": "Use AI-assisted development productively while retaining engineering judgment and validation.", "Learning Type (SPL / IL)": "SPL"}'),
	(30, 1, 42, 'Day 28', 'Quality & Resilience Hardening (Extended Test Coverage)', '{"Day": "Day 28", "Week": "Week 7", "Topic": "Quality & Resilience Hardening (Extended Test Coverage)", "Module": "Full Stack Engineering", "Source": "PACKT", "Remarks": "Include modules\nGetting Started With Cypress Automation - 55m\nWeb UI Interactions - 1hr 26m\nFramework Preparation - 1hr \nPage Object Model Framework - 49m\nReporting And Cloud Dashboard - 51m\nContinuous Integration With Jenkins - 59m\nCypress Assertions - 27m\nAPI Testing Concepts - 42m\nCypress API Automation - 1hr 35m\nfrom given course", "Duration": "2:55:00\n8:44:00", "Sub Topic": "Expanded unit and component test coverage using Jasmine/Karma (frontend) and JUnit/Mockito (backend)\nIntegration tests for authenticated API-driven user journeys\nBasic end-to-end validation of the most critical business path\nAccessibility checks for labels, keyboard behavior, focus and readable feedback\nPerformance sanity checks for rendering, loading and repeated network activity\nError-scenario and edge-case testing for empty, invalid, unauthorized and server-failure responses\nRegression evidence and repeatable test execution suitable for CI/CD\nCreation of a consolidated quality evidence pack for final readiness review", "Proficiency": "Advanced", "Hands-on Labs": "Case Study – Quality & Resilience Hardening\nInput: Authenticated PulseCart Angular feature and existing automated tests.\nImplement: Expand Jasmine/Karma unit/component tests, integration checks and one critical E2E-basic flow; add accessibility, performance and edge-case validation.\nIntegrate: Run the quality checks against the same end-to-end feature and connect repeatable checks to the CI/CD workflow.\nValidate: Prove positive, negative, authorization, accessibility, performance and backend-failure scenarios.\nOutput: Consolidated engineering-quality evidence pack for the PulseCart feature.\nEvidence: Test results, accessibility/performance findings, defect fixes and CI/CD execution evidence.", "Duration (Hrs)": "4", "Published Date": "3/11/26", "Total Duration": "11:39:00", "Course / You tube": "Complete TDD Course - Java Unit Testing with Mockito Framework\nCypress Automation Testing Framework V13 - Novice To Ninja", "Learning Outcomes": "Produce a consolidated quality evidence pack with unit/component, integration, E2E-basic, accessibility, performance and edge-case validation embedded into hands-on work.", "Learning Type (SPL / IL)": "SPL", "Customised course names for Skill Assist": "Cypress Automation Testing Framework V13 - Novice To Ninja - Sony Java with Angular"}'),
	(31, 1, 47, 'Day 29', 'Capstone Day 1 – Build: Requirements-to-Working Feature', '{"Day": "Day 29", "Week": "Week 7", "Topic": "Capstone Day 1 – Build: Requirements-to-Working Feature", "Module": "Capstone Project", "Sub Topic": "Independently clarify the authenticated ticket-cancellation-and-refund user story and its acceptance criteria (reason, ticket, refund method, status workflow Requested → Approved/Rejected → Refunded) — a brand-new capability on a brand-new platform, not a continuation of PulseCart; design and implement the Java Spring Boot REST endpoints and JPA entities for the cancellation/refund request and its status workflow; implement the Angular journey for a customer to request a cancellation and track its status, plus a box-office/support-agent view to approve/reject; apply Spring Security JWT authentication/authorization so a customer can only act on their own tickets and only an agent role can approve/reject; build entirely from an empty capstone baseline, not the PulseCart codebase or its catalog/order data model.", "Hands-on Labs": "Case Study – Cadence Live: Authenticated Ticket Cancellation & Refund Management – Build\nInput: The Cadence Live capstone build requirements, representative ticket/order API payloads, and the existing capstone project baseline (an empty repository/workspace) — an independent, unseen case study, not a continuation of PulseCart OneJourney.\nImplement: Design and implement the Spring Boot REST API and status workflow for ticket cancellation & refunds, then deliver the matching Angular customer and agent journeys with authenticated access.\nIntegrate: This is the seed of the whole capstone — nothing to reuse from PulseCart''s catalog/order model; every later day traces back to the decisions made here.\nValidate: Run the feature end to end, verify success/failure behavior, and confirm role-based access is enforced in both directions.\nOutput: Working, authenticated ticket-cancellation-and-refund feature for Cadence Live, built independently.\nEvidence: Spring Boot contract & entities, Angular customer journey and Angular agent journey; screenshots/test output; a short implementation note.", "Duration (Hrs)": "4", "Learning Outcomes": "Independently create an integrated, role-aware cross-layer feature — ticket cancellation & refund management — spanning the Java Spring Boot backend and the Angular frontend, on a platform never seen before.", "Learning Type (SPL / IL)": "Capstone"}'),
	(32, 1, 48, 'Day 30', 'Capstone Day 2 – Automate & Test: Production-Readiness Hardening', '{"Day": "Day 30", "Week": "Week 7", "Topic": "Capstone Day 2 – Automate & Test: Production-Readiness Hardening", "Module": "Capstone Project", "Sub Topic": "Add JUnit/Mockito unit/integration tests and Jasmine/Karma unit/component tests for the cancellation-and-refund workflow and its status transitions; validate negative, unauthorized (customer acting on another customer''s ticket, or a non-agent attempting to approve) and backend-failure scenarios; apply secure coding and safe token/data-handling practices; review accessibility and performance basics for the Angular journeys; connect build/test checks to the CI/CD path; add logging/observability evidence for troubleshooting refund-status changes.", "Hands-on Labs": "Case Study – Cadence Live: Authenticated Ticket Cancellation & Refund Management – Production Readiness\nInput: The Day 29 Cadence Live feature (Spring Boot contract & entities, Angular customer and agent journeys), plus the capstone hardening and quality requirements.\nImplement: Complete JUnit/Mockito + Jasmine/Karma tests, secure handling, failure scenarios, logging/observability evidence and CI/CD wiring for both layers.\nIntegrate: Every test, security fix and pipeline check targets the exact feature built independently in Day 29 — not a hardening exercise on sample or PulseCart code.\nValidate: Confirm positive, negative, unauthorized and backend-failure scenarios all pass on both layers; confirm the CI/CD path runs the new checks.\nOutput: Layered test suite, secure-coding review and CI/CD-connected quality evidence for the Cadence Live feature.\nEvidence: JUnit/Mockito + Jasmine/Karma results, secure-coding review notes, accessibility/performance findings, CI/CD run evidence, logging/observability evidence.", "Duration (Hrs)": "4", "Learning Outcomes": "Prepare the independently-built Cadence Live cancellation-and-refund feature for a production-readiness demo with quality, security, deployment and observability evidence.", "Learning Type (SPL / IL)": "Capstone"}'),
	(46, 2, 19, 'Day 10', 'Case Lab: AI-Integrated Data Feature Assembly', '{"Day": "Day 10", "Week": "Week 2", "Topic": "Case Lab: AI-Integrated Data Feature Assembly", "Module": "AI-Integrated Data & Analytics Engineering", "Sub Topic": "This is a consolidation session for the AI workstream. Participants combine the integration design, the RAG pipeline, the agentic workflow and the evaluation plan from the previous four sessions into one complete, presentable design for the AI-powered feature, and walk their peers through it for feedback -- the same way they would present a feature design to a product or engineering leadership team.", "Learning Type": "SPL", "Duration (Hrs)": "2", "Hands-on Activity": "Combine the integration pattern, RAG design, agentic workflow and evaluation plan from Sessions 1-4 into one complete AI-integrated feature design for Meridian Financial Group, and present it for peer critique.", "Learning Outcomes": "Consolidated AI-integrated feature design package (v1), layered onto the Module 1 architecture package."}'),
	(33, 1, 49, 'Day 31', 'Capstone Day 3 – Respond & Improve: Resilience & Edge-Case Hardening', '{"Day": "Day 31", "Week": "Week 7", "Topic": "Capstone Day 3 – Respond & Improve: Resilience & Edge-Case Hardening", "Module": "Capstone Project", "Sub Topic": "Simulate a backend failure/timeout during a refund-status update end-to-end (detect, communicate, mitigate) across the Java Spring Boot backend and the Angular frontend; expand automated test coverage for newly hardened edge cases (duplicate cancellation requests, refund on an already-refunded ticket); add correlation-friendly logging so a user-visible error can be traced to the originating request; implement at least one reliability/UX improvement from the findings and update the implementation note.", "Hands-on Labs": "Case Study – Cadence Live: Authenticated Ticket Cancellation & Refund Management – Resilience Hardening\nInput: The Day 29 feature and the Day 30 test/security/CI/CD hardening package.\nImplement: Simulate a backend failure/timeout during a refund-status update, capture failure-path evidence, and implement at least one reliability/UX improvement across the Java backend and Angular frontend.\nIntegrate: The failure simulation runs against the same feature and tests built independently in Days 29–30 — a review of the whole Cadence Live feature as it now stands.\nValidate: Confirm the failure is detected, communicated and mitigated; confirm new tests fail pre-fix and pass post-fix.\nOutput: Simulated-failure evidence, expanded edge-case tests and a shipped reliability/UX improvement for the Cadence Live feature.\nEvidence: Failure-path evidence, expanded tests, correlation-friendly logging output, the shipped improvement and updated implementation note.", "Duration (Hrs)": "4", "Learning Outcomes": "Demonstrate resilient, cross-layer failure handling and evidence-based reliability improvement on the independently-built Cadence Live cancellation-and-refund feature.", "Learning Type (SPL / IL)": "Capstone"}'),
	(34, 1, 50, 'Day 32', 'Capstone Day 4 – Harden, Document & Demo', '{"Day": "Day 32", "Week": "Week 7", "Topic": "Capstone Day 4 – Harden, Document & Demo", "Module": "Capstone Project", "Sub Topic": "Finalize the CI/CD deployment path for both the Java Spring Boot backend and the Angular frontend; assemble the complete evidence pack (source code, test/CI evidence, security review, accessibility/performance findings, logging/observability evidence, acceptance-criteria traceability) for the cancellation-and-refund feature; rehearse and deliver the end-to-end capstone demonstration across the backend and frontend, on a platform independent of PulseCart.", "Hands-on Labs": "Case Study – Cadence Live: Authenticated Ticket Cancellation & Refund Management – Harden, Document & Demo\nInput: All outputs from Days 29–31 on Cadence Live.\nImplement: Finalize the CI/CD deployment path for both layers, assemble the full evidence pack, and rehearse/deliver the end-to-end capstone demonstration.\nIntegrate: The demonstration walks through the single, continuous Cadence Live feature — Day 29''s journeys, Day 30''s quality/security evidence, Day 31''s resilience evidence — as one story.\nValidate: Confirm the deployment path runs end to end for both layers; confirm every acceptance criterion is traceable to evidence.\nOutput: Finalized CI/CD deployment path, complete production-readiness evidence pack, and rehearsed end-to-end demonstration for Cadence Live.\nEvidence: Capstone repo/release, demo, tests, security review, CI/CD evidence, logging/observability evidence, all traced to acceptance criteria.", "Duration (Hrs)": "4", "Learning Outcomes": "Deliver a production-readiness demo of an independently-built feature (Cadence Live ticket cancellation & refund management) with quality, security, deployment and acceptance-criteria evidence, ready for Milestone / SME review.", "Learning Type (SPL / IL)": "Capstone"}'),
	(35, 2, 5, '—', 'Pre-Assessment (Prerequisites)', '{"Day": "—", "Week": "Pre-Program", "Topic": "Pre-Assessment (Prerequisites)", "Module": "Prerequisite Validation & Orientation", "Sub Topic": "Baseline readiness check covering all prerequisite areas before the program begins — see the Prerequisites & Audience sheet for the full list. Confirms starting proficiency; does not gate attendance on its own.", "Learning Type": "SPL", "Duration (Hrs)": "1.5", "Hands-on Activity": "—", "Learning Outcomes": "Baseline readiness confirmed across all prerequisite areas; any gaps are flagged for pre-work before Day 1."}'),
	(36, 2, 6, '—', 'Program Orientation', '{"Day": "—", "Week": "Pre-Program", "Topic": "Program Orientation", "Module": "Prerequisite Validation & Orientation", "Sub Topic": "Program kickoff: introduce the Meridian Financial Group case study and the full program journey, walk through the curriculum structure, Milestone / Interview Bot / Capstone checkpoints, tooling and environment setup, and readiness criteria; address questions before Day 1 begins.", "Learning Type": "IL", "Duration (Hrs)": "2", "Hands-on Activity": "—", "Learning Outcomes": "The program structure is understood, tooling access is confirmed, and expectations are clear before Day 1."}'),
	(37, 2, 8, 'Day 1', 'Data Architecture Thinking & Pattern Selection', '{"Day": "Day 1", "Week": "Week 1", "Topic": "Data Architecture Thinking & Pattern Selection", "Module": "Data Architecture Foundations & Practice", "Sub Topic": "Participants learn to think and design at the platform level rather than the pipeline level. The session walks through the major data-platform architecture patterns used today -- batch warehousing, streaming/event-driven pipelines, the lakehouse pattern and data mesh -- comparing their strengths, trade-offs and best-fit scenarios with real examples. Participants then practice selecting and justifying the right pattern combination for a real business scenario, instead of defaulting to whichever pattern they already know best.", "Learning Type": "SPL", "Duration (Hrs)": "2", "Hands-on Activity": "Kick off Meridian Financial Group — Customer 360 & Analytics Platform: review the business brief for the Customer 360 platform (Account, Transaction, Interaction and Product data sources), select a data-architecture pattern combination, and document an initial system context diagram.", "Learning Outcomes": "Pattern-selection brief and system context diagram (v1) opening the Meridian Financial Group architecture package."}'),
	(38, 2, 9, 'Day 2', 'Data NFRs & Fitness Functions', '{"Day": "Day 2", "Week": "Week 1", "Topic": "Data NFRs & Fitness Functions", "Module": "Data Architecture Foundations & Practice", "Sub Topic": "Participants learn how to turn business expectations -- such as ''customer data must be queryable within seconds of an interaction'' or ''transaction records must never be lost'' -- into specific, measurable targets for throughput, freshness, consistency and durability. The session then shows how to encode these targets as automated checks, called fitness functions, that run continuously and flag the platform the moment it drifts from what was promised, rather than the problem being discovered only after a report goes wrong.", "Learning Type": "IL", "Duration (Hrs)": "3", "Hands-on Activity": "Using the context diagram from the previous session, define data NFRs for the Transaction data source (freshness, throughput, durability targets) and draft one executable fitness function to guard the highest-priority NFR in the data pipeline.", "Learning Outcomes": "Data NFR specification and fitness-function sketch appended to the Meridian Financial Group architecture package."}'),
	(90, 4, 4, NULL, 'Trainer-Led Orientation', '{"Week": "Pre-Program", "Topic": "Trainer-Led Orientation", "Module": "Program Orientation", "Sub Topic": "Program kickoff led by the Trainer: introduce the PulseCart OneJourney case study and the 39-session journey, walk through the curriculum structure, Milestone/Interview Bot/Capstone checkpoints, tooling and environment setup, and readiness/scoring criteria; address learner questions before Day 1 begins.", "Hands-on Labs": "Environment/tooling access confirmed + orientation attendance record.", "Duration (Hrs)": "2", "Learning Outcomes": "Learners understand the program structure, tooling access is verified, and expectations/readiness criteria are clear before Day 1."}'),
	(40, 2, 11, 'Day 4', 'Capacity Planning, Performance Diagnosis & Pipeline Resilience', '{"Day": "Day 4", "Week": "Week 1", "Topic": "Capacity Planning, Performance Diagnosis & Pipeline Resilience", "Module": "Data Architecture Foundations & Practice", "Sub Topic": "Participants learn how to estimate, before a pipeline goes live, whether it will hold up under real-world data volume -- for example, how many transaction events it can ingest per second before it falls behind -- and how to spot likely bottlenecks such as a slow join, an undersized cluster or a skewed partition. The session then introduces Failure Mode and Effects Analysis (FMEA), a structured way of asking ''what could go wrong here, and how bad would it be?'' for every stage of the pipeline. Participants use the answers to design resilience patterns -- such as replay queues, dead-letter handling and checkpointing -- so that when something does fail, the pipeline recovers cleanly instead of silently losing or duplicating data.", "Learning Type": "IL", "Duration (Hrs)": "4", "Hands-on Activity": "Build a capacity model and performance budget for the Transaction data pipeline using the NFRs from Session 2, then run a Failure Mode and Effects Analysis against the same pipeline and design resilience patterns for the top failure modes identified.", "Learning Outcomes": "Capacity model, FMEA worksheet and resilience pattern map, all scoped to the Transaction data pipeline."}'),
	(41, 2, 12, 'Day 5', 'Case Lab: End-to-End Data Platform Architecture Design', '{"Day": "Day 5", "Week": "Week 1", "Topic": "Case Lab: End-to-End Data Platform Architecture Design", "Module": "Data Architecture Foundations & Practice", "Sub Topic": "This is a consolidation session. Participants bring together everything produced across the module -- the pattern decision, the NFRs, the ADR, the capacity model and the resilience plan -- into a single, coherent end-to-end architecture document for the case-study platform. Participants then present this design to their peers and respond to questions and challenges, practicing how to defend a design decision under scrutiny, the way they would in a real client or leadership review.", "Learning Type": "SPL", "Duration (Hrs)": "4", "Hands-on Activity": "Combine the pattern decision, NFRs, ADR, capacity model and resilience plan from Sessions 1-4 into the complete Meridian Financial Group Customer 360 distributed-system design, and present it for peer critique.", "Learning Outcomes": "Consolidated Meridian Financial Group architecture design package (v1) -- the baseline every later module builds on."}'),
	(42, 2, 15, 'Day 7', 'LLM Integration Patterns for Data Platforms & Responsible AI Checkpoints', '{"Day": "Day 7", "Week": "Week 2", "Topic": "LLM Integration Patterns for Data Platforms & Responsible AI Checkpoints", "Module": "AI-Integrated Data & Analytics Engineering", "Sub Topic": "Participants learn the common patterns for adding an AI-powered capability -- such as a natural-language data-query assistant or an AI-assisted cataloging tool -- into an existing data platform: where it plugs in, what data it needs, and how it communicates with the rest of the platform. Alongside this, the session introduces responsible-AI checkpoints -- practical questions the team should ask before building an AI feature over customer data, covering data privacy, bias and misuse risk -- so governance is built in from day one rather than added as an afterthought.", "Learning Type": "SPL", "Duration (Hrs)": "2", "Hands-on Activity": "Using the Meridian Financial Group architecture package, identify where a proposed natural-language analytics assistant fits into the existing Customer 360 design, map the integration pattern, and add a responsible-AI checklist to the existing ADR log.", "Learning Outcomes": "LLM integration-point diagram and responsible-AI checklist appended to the Meridian Financial Group architecture package."}'),
	(43, 2, 16, 'Day 8', 'RAG & Vector Search Architecture over Enterprise Data', '{"Day": "Day 8", "Week": "Week 2", "Topic": "RAG & Vector Search Architecture over Enterprise Data", "Module": "AI-Integrated Data & Analytics Engineering", "Sub Topic": "Participants learn how to design a Retrieval-Augmented Generation (RAG) pipeline with vector search -- a widely used way of making an AI feature answer questions using a company''s own data (like customer transaction history) instead of only what the AI model already knows. The session compares the three main ways to customize an AI model''s behaviour -- fine-tuning, prompt engineering and RAG -- and teaches participants how to choose the right one based on cost, how often the underlying data changes, and how accurate the answers need to be.", "Learning Type": "IL", "Duration (Hrs)": "3", "Hands-on Activity": "Design a RAG pipeline with vector search over the Meridian Financial Group customer-interaction history to power the natural-language analytics assistant scoped in the previous session, and justify a customization strategy against the platform''s freshness and cost constraints.", "Learning Outcomes": "RAG architecture design and customization trade-off decision appended to the Meridian Financial Group package."}'),
	(44, 2, 17, 'Day 9', 'Agentic Data Workflows & AI Cost Economics', '{"Day": "Day 9", "Week": "Week 2", "Topic": "Agentic Data Workflows & AI Cost Economics", "Module": "AI-Integrated Data & Analytics Engineering", "Sub Topic": "Participants learn how to design an ''agentic'' AI workflow for a data platform -- one where the AI does not just answer a single question but carries out a short sequence of steps on the user''s behalf, such as checking a customer''s transaction history and then flagging a data-quality issue for review. The session also covers how to estimate what an AI feature will actually cost to run once real users are using it at scale, so the business can make an informed decision before committing budget to the feature.", "Learning Type": "SPL", "Duration (Hrs)": "2", "Hands-on Activity": "Extend the RAG design from the previous session into a lightweight agentic workflow covering customer lookup and data-quality flagging, and estimate monthly AI spend for the Meridian Financial Group platform at three usage scales.", "Learning Outcomes": "Agent architecture diagram and cost model, both scoped to the same analytics-assistant feature."}'),
	(45, 2, 18, 'Day 9', 'AI Evaluation, Observability & Governance for Data Features', '{"Day": "Day 9", "Week": "Week 2", "Topic": "AI Evaluation, Observability & Governance for Data Features", "Module": "AI-Integrated Data & Analytics Engineering", "Sub Topic": "Participants learn how to keep an AI feature trustworthy after it goes live, not just at launch. The session covers how to test AI responses for accuracy before release, how to monitor an AI feature in production -- tracking things like response speed and how often it gives an incorrect or made-up answer about a customer''s data -- and how to set up automatic guardrails that catch a decline in quality before business users notice it.", "Learning Type": "IL", "Duration (Hrs)": "2", "Hands-on Activity": "Define the evaluation and observability plan -- offline/online evaluation, latency and hallucination-rate monitoring, regression gates -- for the Meridian Financial Group analytics-assistant feature built across Sessions 1-3.", "Learning Outcomes": "Evaluation and observability plan for the analytics-assistant feature."}'),
	(186, 6, 36, NULL, 'Reliability and delivery guarantees', '{"Topic": "Reliability and delivery guarantees", "Sub-Category": "Azure Service Bus", "Assessment Area": "Azure"}'),
	(187, 6, 37, NULL, 'Core Java and OOP fundamentals', '{"Topic": "Core Java and OOP fundamentals", "Assessment Area": "Java 8 to Java 25"}'),
	(47, 2, 22, 'Day 12', 'Well-Architected Review & Multi-Service Cloud Data Platform Design', '{"Day": "Day 12", "Week": "Week 3", "Topic": "Well-Architected Review & Multi-Service Cloud Data Platform Design", "Module": "Cloud Data Platform Engineering", "Sub Topic": "Participants learn how to run a Well-Architected review -- a structured checklist, used across all major cloud providers, that examines a design for cost efficiency, security, reliability and performance before it is built. Using the outcome of that review, participants then design how the data platform will actually be laid out across multiple cloud services -- ingestion, storage, warehouse/lakehouse compute and orchestration -- working together, rather than treating cloud deployment as a single black box.", "Learning Type": "IL", "Duration (Hrs)": "4", "Hands-on Activity": "Run a Well-Architected review against the Meridian Financial Group design produced in Modules 1-2, then design the multi-service cloud topology -- ingestion, storage and compute -- that will host the platform, including the AI-integrated feature.", "Learning Outcomes": "Well-Architected trade-off analysis and multi-service cloud architecture diagram for Meridian Financial Group."}'),
	(48, 2, 23, 'Day 13', 'Infrastructure as Code for Data Platforms', '{"Day": "Day 13", "Week": "Week 3", "Topic": "Infrastructure as Code for Data Platforms", "Module": "Cloud Data Platform Engineering", "Sub Topic": "Participants learn how to turn a cloud data-platform architecture diagram into Infrastructure as Code (IaC) -- reusable, version-controlled scripts that create the pipelines, storage and warehouse environment automatically and consistently every time, instead of engineers manually clicking through a cloud console. This makes environments repeatable, auditable and far faster to stand up or tear down.", "Learning Type": "SPL", "Duration (Hrs)": "2", "Hands-on Activity": "Translate the cloud architecture diagram from the previous session into a golden-path Infrastructure-as-Code template for the Meridian Financial Group platform.", "Learning Outcomes": "Infrastructure-as-Code template scoped to the Meridian Financial Group platform."}'),
	(49, 2, 24, 'Day 13', 'Multi-Region Resilience & Release Strategy for Data Platforms', '{"Day": "Day 13", "Week": "Week 3", "Topic": "Multi-Region Resilience & Release Strategy for Data Platforms", "Module": "Cloud Data Platform Engineering", "Sub Topic": "Participants learn how to design a data platform so it can survive the failure of an entire cloud region -- for example, if a whole data centre goes offline -- including setting clear recovery targets for how much data the business can afford to lose and how quickly the platform must be back online. The session also covers release strategy: how to roll out new versions of a pipeline or schema safely, with the ability to roll back instantly if something goes wrong.", "Learning Type": "IL", "Duration (Hrs)": "2", "Hands-on Activity": "Design a multi-region disaster-recovery strategy and a release/rollback plan for the Meridian Financial Group platform, building directly on the Infrastructure-as-Code baseline from the previous session.", "Learning Outcomes": "Disaster-recovery strategy and release plan for the Meridian Financial Group platform."}'),
	(50, 2, 25, 'Day 14', 'Case Lab: Data Platform Reliability & Cost Optimization', '{"Day": "Day 14", "Week": "Week 3", "Topic": "Case Lab: Data Platform Reliability & Cost Optimization", "Module": "Cloud Data Platform Engineering", "Sub Topic": "This is a consolidation session for the cloud workstream. Participants bring together the cloud architecture, the Infrastructure-as-Code setup and the disaster-recovery/release plan into a single platform reliability plan, and add a cost-optimization pass -- identifying where the platform is over-provisioned or paying for storage/compute capacity it does not need.", "Learning Type": "SPL", "Duration (Hrs)": "2", "Hands-on Activity": "Combine the cloud architecture, Infrastructure-as-Code baseline and disaster-recovery/release plan from Sessions 1-3 into an end-to-end platform reliability plan for Meridian Financial Group, including a cost-optimization pass.", "Learning Outcomes": "Consolidated cloud deployment package (v1), layered onto the architecture and AI-feature packages."}'),
	(51, 2, 28, 'Day 16', 'Data Security Architecture & Vulnerability Management', '{"Day": "Day 16", "Week": "Week 4", "Topic": "Data Security Architecture & Vulnerability Management", "Module": "Data Governance, Security & Compliance Engineering", "Sub Topic": "Participants learn how to build security into the data platform itself -- deciding upfront how data will be encrypted at rest and in transit, and who is allowed to access which datasets -- rather than adding security as an afterthought. The session also covers how to run a basic vulnerability assessment against a data platform to identify its weak points, and how to set up a workflow for fixing what is found, so vulnerability management becomes an ongoing habit rather than a one-time audit.", "Learning Type": "SPL", "Duration (Hrs)": "2", "Hands-on Activity": "Thread-model the Meridian Financial Group platform as designed across Modules 1-3, identify the highest-priority vulnerabilities, and draft a remediation plan for the same architecture.", "Learning Outcomes": "Threat model and remediation plan for the Meridian Financial Group platform."}'),
	(52, 2, 29, 'Day 16', 'Zero Trust & Identity-Centric Design for Data Access', '{"Day": "Day 16", "Week": "Week 4", "Topic": "Zero Trust & Identity-Centric Design for Data Access", "Module": "Data Governance, Security & Compliance Engineering", "Sub Topic": "Participants learn Zero Trust: the principle that no request should be trusted by default, even if it comes from inside the company network, and every access request to a dataset must be verified based on identity. The session teaches participants how to redesign an existing data platform''s access boundaries around this principle -- including row- and column-level access control -- moving away from the older idea of a single secure ''perimeter'' wrapped around the whole platform.", "Learning Type": "IL", "Duration (Hrs)": "2", "Hands-on Activity": "Redesign the Meridian Financial Group platform''s access boundaries using zero-trust principles, building directly on the threat model from the previous session.", "Learning Outcomes": "Zero-trust design for the Meridian Financial Group platform."}'),
	(53, 2, 30, 'Day 17', 'Regulatory Compliance & Continuous Compliance Automation', '{"Day": "Day 17", "Week": "Week 4", "Topic": "Regulatory Compliance & Continuous Compliance Automation", "Module": "Data Governance, Security & Compliance Engineering", "Sub Topic": "Participants learn how to map relevant regulatory requirements -- such as data-privacy or financial-services-specific rules -- directly onto the data platform, so compliance is designed in rather than checked at the end. The session also covers how to automate at least one compliance check, such as automatically verifying that sensitive customer fields are encrypted or masked, so evidence of compliance is collected continuously instead of scrambled together during an annual audit.", "Learning Type": "SPL", "Duration (Hrs)": "2", "Hands-on Activity": "Map relevant compliance requirements onto the Meridian Financial Group architecture and automate one control check as a continuous compliance safeguard.", "Learning Outcomes": "Compliance mapping and one automated control check for the Meridian Financial Group platform."}'),
	(188, 6, 38, NULL, 'Java 8 features: lambda expressions and functional interfaces', '{"Topic": "Java 8 features: lambda expressions and functional interfaces", "Assessment Area": "Java 8 to Java 25"}'),
	(54, 2, 31, 'Day 17', 'Case Lab: Secure & Governed Data Architecture Review', '{"Day": "Day 17", "Week": "Week 4", "Topic": "Case Lab: Secure & Governed Data Architecture Review", "Module": "Data Governance, Security & Compliance Engineering", "Sub Topic": "This is a consolidation session for the security and governance workstream. Participants bring together the threat model, the zero-trust redesign and the compliance mapping into one complete secure-architecture review, and produce a prioritized roadmap listing which security and governance gaps need to be fixed first and why -- the kind of document a security or compliance lead would expect to see before sign-off.", "Learning Type": "IL", "Duration (Hrs)": "2", "Hands-on Activity": "Consolidate the threat model, zero-trust design and compliance mapping from Sessions 1-3 into a full secure-architecture review of Meridian Financial Group, and present a remediation roadmap.", "Learning Outcomes": "Consolidated security and governance package (v1), layered onto the cumulative Meridian Financial Group design."}'),
	(55, 2, 34, 'Day 19', 'Translating Data Architecture to Business Language & Influence Without Authority', '{"Day": "Day 19", "Week": "Week 4", "Topic": "Translating Data Architecture to Business Language & Influence Without Authority", "Module": "Business Translation & Leadership", "Sub Topic": "Participants learn how to explain data-architecture decisions and trade-offs to non-technical stakeholders -- leadership, product managers, clients -- in language they can act on, without oversimplifying or losing important nuance. The session also covers how to negotiate for a technical priority, such as extra time to close a data-quality gap, when the participant has no formal authority over the other team, through a realistic negotiation role-play.", "Learning Type": "IL", "Duration (Hrs)": "4", "Hands-on Activity": "Build a stakeholder pitch for the complete Meridian Financial Group platform -- architecture, AI feature, cloud deployment and security posture -- and rehearse a negotiation for one contested trade-off with a peer playing a resistant stakeholder.", "Learning Outcomes": "Stakeholder pitch deck and negotiation notes for the complete Meridian Financial Group platform."}'),
	(56, 2, 35, 'Day 20', 'Cost/ROI Framing & Change Leadership', '{"Day": "Day 20", "Week": "Week 4", "Topic": "Cost/ROI Framing & Change Leadership", "Module": "Business Translation & Leadership", "Sub Topic": "Participants learn how to present a technical decision in the terms the business cares about most -- cost and return on investment -- rather than purely technical merit. The session also covers change leadership: how to plan and sequence the rollout of a new data platform or process in a way that anticipates resistance from the teams affected by the change, instead of assuming everyone will adopt it automatically.", "Learning Type": "SPL", "Duration (Hrs)": "2", "Hands-on Activity": "Build a cost/ROI one-pager for the Meridian Financial Group platform and a phased rollout plan for taking it into production.", "Learning Outcomes": "ROI one-pager and phased rollout plan for the Meridian Financial Group platform."}'),
	(57, 2, 36, 'Day 20', 'Build vs Buy & Vendor Evaluation', '{"Day": "Day 20", "Week": "Week 4", "Topic": "Build vs Buy & Vendor Evaluation", "Module": "Business Translation & Leadership", "Sub Topic": "Participants learn a structured framework for deciding whether to build a data-platform capability in-house or buy it from a vendor -- weighing cost, time-to-market, control and long-term maintenance -- instead of defaulting to whichever option the team is most comfortable with. The session also covers how to run a basic vendor evaluation, comparing options against the same criteria side by side.", "Learning Type": "SPL", "Duration (Hrs)": "2", "Hands-on Activity": "Apply a build-vs-buy scoring framework to one Meridian Financial Group component -- the analytics-assistant vendor-vs-in-house decision -- completing the Meridian Financial Group evidence pack.", "Learning Outcomes": "Build-vs-buy scorecard, completing the final version of the Meridian Financial Group evidence pack."}'),
	(58, 2, 40, 'Day 23', 'Capstone Day 1 — Architect the Platform', '{"Day": "Day 23", "Week": "Week 5", "Topic": "Capstone Day 1 — Architect the Platform", "Module": "Capstone Project", "Sub Topic": "Use Case: Harborview Logistics — Supply Chain Data Platform — a supply chain data platform (shipment tracking, warehouse inventory, carrier performance and demand-forecasting data) that the learner has not worked on during the program. Apply the architecture-practice skill set independently: pattern selection, non-functional requirements, Architecture Decision Records and a distributed-system design, on a new platform and without step-by-step guidance.", "Learning Type": "Capstone", "Duration (Hrs)": "4", "Hands-on Activity": "Independently architect the Harborview Logistics platform end to end: select an architecture pattern combination, define NFRs, write the supporting ADRs, and produce a distributed-system design for the core supply-chain data flow.", "Learning Outcomes": "Harborview Logistics architecture design package: pattern decision, NFR specification, ADR set and system design."}'),
	(59, 2, 41, 'Day 24', 'Capstone Day 2 — Integrate AI & Deploy to Cloud', '{"Day": "Day 24", "Week": "Week 5", "Topic": "Capstone Day 2 — Integrate AI & Deploy to Cloud", "Module": "Capstone Project", "Sub Topic": "Extend the Day 1 architecture with an AI-powered demand-forecasting assistant and deploy the resulting platform to the cloud using Infrastructure as Code, applying the AI-integration and cloud-deployment skill sets independently to the new platform.", "Learning Type": "Capstone", "Duration (Hrs)": "4", "Hands-on Activity": "Design and integrate an AI-powered demand-forecasting assistant into the Day 1 architecture, then translate the resulting platform into a multi-service cloud design and an Infrastructure-as-Code deployment baseline.", "Learning Outcomes": "AI-integrated feature design and cloud deployment package for the Harborview Logistics platform."}'),
	(60, 2, 42, 'Day 25', 'Capstone Day 3 — Secure, Comply & Build the Business Case', '{"Day": "Day 25", "Week": "Week 5", "Topic": "Capstone Day 3 — Secure, Comply & Build the Business Case", "Module": "Capstone Project", "Sub Topic": "Secure the platform built on Days 1-2, map it against relevant compliance requirements, and build the stakeholder business case, applying the security and business-translation skill sets independently to close out the capstone build.", "Learning Type": "Capstone", "Duration (Hrs)": "4", "Hands-on Activity": "Thread-model and secure the Harborview Logistics platform, map it against relevant compliance requirements, and build the stakeholder pitch and cost/ROI case for taking it into production.", "Learning Outcomes": "Security and compliance package plus stakeholder pitch and ROI case for the Harborview Logistics platform."}'),
	(189, 6, 39, NULL, 'Streams API and Optional', '{"Topic": "Streams API and Optional", "Assessment Area": "Java 8 to Java 25"}'),
	(190, 6, 40, NULL, 'Default methods and the new Date/Time API', '{"Topic": "Default methods and the new Date/Time API", "Assessment Area": "Java 8 to Java 25"}'),
	(191, 6, 41, NULL, 'Collections framework and generics', '{"Topic": "Collections framework and generics", "Assessment Area": "Java 8 to Java 25"}'),
	(192, 6, 42, NULL, 'Exception handling', '{"Topic": "Exception handling", "Assessment Area": "Java 8 to Java 25"}'),
	(61, 2, 43, 'Day 26', 'Capstone Evaluation & Panel Review', '{"Day": "Day 26", "Week": "Week 6", "Topic": "Capstone Evaluation & Panel Review", "Module": "Capstone Project", "Sub Topic": "Participants present the complete Harborview Logistics capstone -- covering architecture, AI integration, cloud deployment, security and the business case -- to a review panel made up of the trainer and, where available, a client-side stakeholder. Participants respond to panel questions and defend their design decisions, the same way they would in a real project sign-off or client review.", "Learning Type": "Panel Review", "Duration (Hrs)": "4", "Hands-on Activity": "Deliver an end-to-end walkthrough of the Harborview Logistics capstone to a panel (trainer and, where available, a client-side stakeholder); respond to panel questioning on architecture, AI-integration, cloud, security and business-case decisions.", "Learning Outcomes": "Panel-scored capstone evaluation, covering design command, trade-off articulation and completeness of the evidence pack."}'),
	(62, 3, 5, '—', 'Pre-Assessment (Prerequisites)', '{"Day": "—", "Week": "Pre-Program", "Topic": "Pre-Assessment (Prerequisites)", "Module": "Prerequisite Validation & Orientation", "Sub Topic": "Baseline readiness check covering all prerequisite areas before the program begins — see the Prerequisites & Audience sheet for the full list. Confirms starting proficiency; does not gate attendance on its own.", "Learning Type": "SPL", "Duration (Hrs)": "1.5", "Hands-on Activity": "—", "Learning Outcomes": "Baseline readiness confirmed across all prerequisite areas; any gaps are flagged for pre-work before Day 1."}'),
	(63, 3, 6, '—', 'Program Orientation', '{"Day": "—", "Week": "Pre-Program", "Topic": "Program Orientation", "Module": "Prerequisite Validation & Orientation", "Sub Topic": "Program kickoff: introduce the Vantage Retail case study and the full program journey, walk through the curriculum structure, Milestone / Interview Bot / Capstone checkpoints, tooling and environment setup, and readiness criteria; address questions before Day 1 begins.", "Learning Type": "IL", "Duration (Hrs)": "2", "Hands-on Activity": "—", "Learning Outcomes": "The program structure is understood, tooling access is confirmed, and expectations are clear before Day 1."}'),
	(64, 3, 8, 'Day 1', 'Architecture Thinking & Pattern Selection', '{"Day": "Day 1", "Week": "Week 1", "Topic": "Architecture Thinking & Pattern Selection", "Module": "Architecture Foundations & Practice", "Sub Topic": "Participants learn to think and design at the system level rather than the feature level. The session walks through the major architecture patterns used today -- microservices, event-driven, API-first and layered architectures -- comparing their strengths, trade-offs and best-fit scenarios with real examples. Participants then practice selecting and justifying the right pattern combination for a real business scenario, instead of defaulting to whichever pattern they already know best.", "Learning Type": "SPL", "Duration (Hrs)": "2", "Hands-on Activity": "Kick off Vantage Retail — Order & Fulfillment Platform: review the business brief for the Order & Fulfillment platform (Catalog, Order, Payment and Notification services), select an architecture pattern combination, and document an initial system context diagram.", "Learning Outcomes": "Pattern-selection brief and system context diagram (v1) opening the Vantage Retail architecture package."}'),
	(65, 3, 9, 'Day 2', 'Non-Functional Requirements & Fitness Functions', '{"Day": "Day 2", "Week": "Week 1", "Topic": "Non-Functional Requirements & Fitness Functions", "Module": "Architecture Foundations & Practice", "Sub Topic": "Participants learn how to turn business expectations -- such as ''the system must handle peak sale-day traffic'' or ''orders must never be lost'' -- into specific, measurable targets for scalability, availability and response time. The session then shows how to encode these targets as automated checks, called fitness functions, that run continuously and flag the design the moment it drifts from what was promised, rather than the problem being discovered only after the system goes live.", "Learning Type": "IL", "Duration (Hrs)": "3", "Hands-on Activity": "Using the context diagram from the previous session, define NFRs for the Order service (availability, latency, throughput targets) and draft one executable fitness function to guard the highest-priority NFR in continuous integration.", "Learning Outcomes": "NFR specification and fitness-function sketch appended to the Vantage Retail architecture package."}'),
	(66, 3, 10, 'Day 3', 'Architecture Decision Records & Review Practice', '{"Day": "Day 3", "Week": "Week 1", "Topic": "Architecture Decision Records & Review Practice", "Module": "Architecture Foundations & Practice", "Sub Topic": "Participants learn how to document and communicate the reasoning behind an architecture decision using an industry-standard format called an Architecture Decision Record (ADR), so anyone joining the project later can understand why a choice was made without having to ask around. The session also covers how to run a structured peer design review -- similar to a code review, but for architecture -- so decisions are challenged and validated by others before they are locked in, rather than approved informally.", "Learning Type": "SPL", "Duration (Hrs)": "2", "Hands-on Activity": "Formalize the pattern decision from Session 1 as an Architecture Decision Record, then run a structured peer review of the NFRs defined in Session 2 and log the review outcomes.", "Learning Outcomes": "ADR-001 and a peer-review log added to the Vantage Retail architecture package."}'),
	(67, 3, 11, 'Day 4', 'Performance Engineering, Failure Mode Analysis & Resilience', '{"Day": "Day 4", "Week": "Week 1", "Topic": "Performance Engineering, Failure Mode Analysis & Resilience", "Module": "Architecture Foundations & Practice", "Sub Topic": "Participants learn how to estimate, before a system goes live, whether it will hold up under real-world load -- for example, how many concurrent orders it can process before it slows down -- and how to spot likely bottlenecks such as a slow database query or an overloaded service. The session then introduces Failure Mode and Effects Analysis (FMEA), a structured way of asking ''what could go wrong here, and how bad would it be?'' for every part of the system. Participants use the answers to design resilience patterns -- such as retries, circuit breakers and fallback responses -- so that when something does fail, the system degrades gracefully (a slower or reduced experience) instead of crashing outright.", "Learning Type": "IL", "Duration (Hrs)": "4", "Hands-on Activity": "Build a capacity model and performance budget for the Order service using the NFRs from Session 2, then run a Failure Mode and Effects Analysis against the same service and design resilience patterns for the top failure modes identified.", "Learning Outcomes": "Capacity model, FMEA worksheet and resilience pattern map, all scoped to the Order service."}'),
	(193, 6, 43, NULL, 'Concurrency and multithreading (Executors, CompletableFuture)', '{"Topic": "Concurrency and multithreading (Executors, CompletableFuture)", "Assessment Area": "Java 8 to Java 25"}'),
	(194, 6, 44, NULL, 'Java 9-11: modules (JPMS), ''var'', new HTTP Client, API updates', '{"Topic": "Java 9-11: modules (JPMS), ''var'', new HTTP Client, API updates", "Assessment Area": "Java 8 to Java 25"}'),
	(241, 6, 91, NULL, 'Error boundaries and testing basics', '{"Topic": "Error boundaries and testing basics", "Assessment Area": "React JS"}'),
	(68, 3, 12, 'Day 5', 'Case Lab: End-to-End Distributed System Design', '{"Day": "Day 5", "Week": "Week 1", "Topic": "Case Lab: End-to-End Distributed System Design", "Module": "Architecture Foundations & Practice", "Sub Topic": "This is a consolidation session. Participants bring together everything produced across the module -- the pattern decision, the NFRs, the ADR, the capacity model and the resilience plan -- into a single, coherent end-to-end architecture document for the case-study platform. Participants then present this design to their peers and respond to questions and challenges, practicing how to defend a design decision under scrutiny, the way they would in a real client or leadership review.", "Learning Type": "SPL", "Duration (Hrs)": "4", "Hands-on Activity": "Combine the pattern decision, NFRs, ADR, capacity model and resilience plan from Sessions 1-4 into the complete Vantage Retail Order & Fulfillment distributed-system design, and present it for peer critique.", "Learning Outcomes": "Consolidated Vantage Retail architecture design package (v1) — the baseline every later module builds on."}'),
	(69, 3, 15, 'Day 7', 'LLM Integration Patterns & Responsible AI Checkpoints', '{"Day": "Day 7", "Week": "Week 2", "Topic": "LLM Integration Patterns & Responsible AI Checkpoints", "Module": "AI-Integrated Feature Engineering", "Sub Topic": "Participants learn the common patterns for adding an AI-powered capability -- such as a chatbot or a recommendation feature -- into an existing application: where it plugs in, what data it needs, and how it communicates with the rest of the system. Alongside this, the session introduces responsible-AI checkpoints -- practical questions the team should ask before building an AI feature, covering data privacy, bias and misuse risk -- so governance is built in from day one rather than added as an afterthought.", "Learning Type": "SPL", "Duration (Hrs)": "2", "Hands-on Activity": "Using the Vantage Retail architecture package, identify where a proposed AI shopping-assistant feature fits into the existing Order & Fulfillment design, map the integration pattern, and add a responsible-AI checklist to the existing ADR log.", "Learning Outcomes": "LLM integration-point diagram and responsible-AI checklist appended to the Vantage Retail architecture package."}'),
	(70, 3, 16, 'Day 8', 'RAG Pipeline Architecture & Customization Trade-offs', '{"Day": "Day 8", "Week": "Week 2", "Topic": "RAG Pipeline Architecture & Customization Trade-offs", "Module": "AI-Integrated Feature Engineering", "Sub Topic": "Participants learn how to design a Retrieval-Augmented Generation (RAG) pipeline -- a widely used way of making an AI feature answer questions using a company''s own data (like a product catalog) instead of only what the AI model already knows. The session compares the three main ways to customize an AI model''s behaviour -- fine-tuning, prompt engineering and RAG -- and teaches participants how to choose the right one based on cost, how often the underlying data changes, and how accurate the answers need to be.", "Learning Type": "IL", "Duration (Hrs)": "3", "Hands-on Activity": "Design a RAG pipeline over the Vantage Retail product catalog to power the shopping-assistant feature scoped in the previous session, and justify a customization strategy against the platform''s freshness and cost constraints.", "Learning Outcomes": "RAG architecture design and customization trade-off decision appended to the Vantage Retail package."}'),
	(71, 3, 17, 'Day 9', 'Agentic Design & AI Cost Economics', '{"Day": "Day 9", "Week": "Week 2", "Topic": "Agentic Design & AI Cost Economics", "Module": "AI-Integrated Feature Engineering", "Sub Topic": "Participants learn how to design an ''agentic'' AI workflow -- one where the AI does not just answer a single question but carries out a short sequence of steps on the user''s behalf, such as searching a catalog and then checking an order''s status. The session also covers how to estimate what an AI feature will actually cost to run once real users are using it at scale, so the business can make an informed decision before committing budget to the feature.", "Learning Type": "SPL", "Duration (Hrs)": "2", "Hands-on Activity": "Extend the RAG design from the previous session into a lightweight agentic workflow covering product search and order-status lookup, and estimate monthly AI spend for the Vantage Retail platform at three usage scales.", "Learning Outcomes": "Agent architecture diagram and cost model, both scoped to the same shopping-assistant feature."}'),
	(72, 3, 18, 'Day 9', 'AI Evaluation, Observability & Governance', '{"Day": "Day 9", "Week": "Week 2", "Topic": "AI Evaluation, Observability & Governance", "Module": "AI-Integrated Feature Engineering", "Sub Topic": "Participants learn how to keep an AI feature trustworthy after it goes live, not just at launch. The session covers how to test AI responses for accuracy before release, how to monitor an AI feature in production -- tracking things like response speed and how often it gives an incorrect or made-up answer -- and how to set up automatic guardrails that catch a decline in quality before customers notice it.", "Learning Type": "IL", "Duration (Hrs)": "2", "Hands-on Activity": "Define the evaluation and observability plan — offline/online evaluation, latency and hallucination-rate monitoring, regression gates — for the Vantage Retail shopping-assistant feature built across Sessions 1-3.", "Learning Outcomes": "Evaluation and observability plan for the shopping-assistant feature."}'),
	(73, 3, 19, 'Day 10', 'Case Lab: AI-Integrated Feature Assembly', '{"Day": "Day 10", "Week": "Week 2", "Topic": "Case Lab: AI-Integrated Feature Assembly", "Module": "AI-Integrated Feature Engineering", "Sub Topic": "This is a consolidation session for the AI workstream. Participants combine the integration design, the RAG pipeline, the agentic workflow and the evaluation plan from the previous four sessions into one complete, presentable design for the AI-powered feature, and walk their peers through it for feedback -- the same way they would present a feature design to a product or engineering leadership team.", "Learning Type": "SPL", "Duration (Hrs)": "2", "Hands-on Activity": "Combine the integration pattern, RAG design, agentic workflow and evaluation plan from Sessions 1-4 into one complete AI-integrated feature design for Vantage Retail, and present it for peer critique.", "Learning Outcomes": "Consolidated AI-integrated feature design package (v1), layered onto the Module 1 architecture package."}'),
	(74, 3, 22, 'Day 12', 'Well-Architected Review & Multi-Service Cloud Design', '{"Day": "Day 12", "Week": "Week 3", "Topic": "Well-Architected Review & Multi-Service Cloud Design", "Module": "Cloud Deployment & Platform Engineering", "Sub Topic": "Participants learn how to run a Well-Architected review -- a structured checklist, used across all major cloud providers, that examines a design for cost efficiency, security, reliability and performance before it is built. Using the outcome of that review, participants then design how the platform will actually be laid out across multiple cloud services -- compute, storage and networking -- working together, rather than treating cloud deployment as a single black box.", "Learning Type": "IL", "Duration (Hrs)": "4", "Hands-on Activity": "Run a Well-Architected review against the Vantage Retail design produced in Modules 1-2, then design the multi-service cloud topology — compute, storage and networking — that will host the platform, including the AI-integrated feature.", "Learning Outcomes": "Well-Architected trade-off analysis and multi-service cloud architecture diagram for Vantage Retail."}'),
	(75, 3, 23, 'Day 13', 'Infrastructure as Code & Platform Engineering', '{"Day": "Day 13", "Week": "Week 3", "Topic": "Infrastructure as Code & Platform Engineering", "Module": "Cloud Deployment & Platform Engineering", "Sub Topic": "Participants learn how to turn a cloud architecture diagram into Infrastructure as Code (IaC) -- reusable, version-controlled scripts that create the cloud environment automatically and consistently every time, instead of engineers manually clicking through a cloud console. This makes environments repeatable, auditable and far faster to stand up or tear down.", "Learning Type": "SPL", "Duration (Hrs)": "2", "Hands-on Activity": "Translate the cloud architecture diagram from the previous session into a golden-path Infrastructure-as-Code template for the Vantage Retail platform.", "Learning Outcomes": "Infrastructure-as-Code template scoped to the Vantage Retail platform."}'),
	(76, 3, 24, 'Day 13', 'Multi-Region Resilience & Release Strategy', '{"Day": "Day 13", "Week": "Week 3", "Topic": "Multi-Region Resilience & Release Strategy", "Module": "Cloud Deployment & Platform Engineering", "Sub Topic": "Participants learn how to design a platform so it can survive the failure of an entire cloud region -- for example, if a whole data centre goes offline -- including setting clear recovery targets for how much data the business can afford to lose and how quickly the platform must be back online. The session also covers release strategy: how to roll out new versions of the platform safely, with the ability to roll back instantly if something goes wrong.", "Learning Type": "IL", "Duration (Hrs)": "2", "Hands-on Activity": "Design a multi-region disaster-recovery strategy and a release/rollback plan for the Vantage Retail platform, building directly on the Infrastructure-as-Code baseline from the previous session.", "Learning Outcomes": "Disaster-recovery strategy and release plan for the Vantage Retail platform."}'),
	(77, 3, 25, 'Day 14', 'Case Lab: Platform Reliability & Cost Optimization', '{"Day": "Day 14", "Week": "Week 3", "Topic": "Case Lab: Platform Reliability & Cost Optimization", "Module": "Cloud Deployment & Platform Engineering", "Sub Topic": "This is a consolidation session for the cloud workstream. Participants bring together the cloud architecture, the Infrastructure-as-Code setup and the disaster-recovery/release plan into a single platform reliability plan, and add a cost-optimization pass -- identifying where the platform is over-provisioned or paying for capacity it does not need.", "Learning Type": "SPL", "Duration (Hrs)": "2", "Hands-on Activity": "Combine the cloud architecture, Infrastructure-as-Code baseline and disaster-recovery/release plan from Sessions 1-3 into an end-to-end platform reliability plan for Vantage Retail, including a cost-optimization pass.", "Learning Outcomes": "Consolidated cloud deployment package (v1), layered onto the architecture and AI-feature packages."}'),
	(78, 3, 28, 'Day 16', 'Security Architecture & Vulnerability Management', '{"Day": "Day 16", "Week": "Week 4", "Topic": "Security Architecture & Vulnerability Management", "Module": "Security & Compliance Engineering", "Sub Topic": "Participants learn how to build security into the architecture itself -- deciding upfront how data will be encrypted and who is allowed to access what -- rather than adding security as an afterthought. The session also covers how to run a basic vulnerability assessment against a design to identify its weak points, and how to set up a workflow for fixing what is found, so vulnerability management becomes an ongoing habit rather than a one-time audit.", "Learning Type": "SPL", "Duration (Hrs)": "2", "Hands-on Activity": "Thread-model the Vantage Retail platform as designed across Modules 1-3, identify the highest-priority vulnerabilities, and draft a remediation plan for the same architecture.", "Learning Outcomes": "Threat model and remediation plan for the Vantage Retail platform."}'),
	(79, 3, 29, 'Day 16', 'Zero Trust & Identity-Centric Design', '{"Day": "Day 16", "Week": "Week 4", "Topic": "Zero Trust & Identity-Centric Design", "Module": "Security & Compliance Engineering", "Sub Topic": "Participants learn Zero Trust: the principle that no request should be trusted by default, even if it comes from inside the company network, and every access request must be verified based on identity. The session teaches participants how to redesign an existing system''s access boundaries around this principle, moving away from the older idea of a single secure ''perimeter'' wrapped around the whole system.", "Learning Type": "IL", "Duration (Hrs)": "2", "Hands-on Activity": "Redesign the Vantage Retail platform''s access boundaries using zero-trust principles, building directly on the threat model from the previous session.", "Learning Outcomes": "Zero-trust design for the Vantage Retail platform."}'),
	(80, 3, 30, 'Day 17', 'Regulatory Compliance & Continuous Compliance Automation', '{"Day": "Day 17", "Week": "Week 4", "Topic": "Regulatory Compliance & Continuous Compliance Automation", "Module": "Security & Compliance Engineering", "Sub Topic": "Participants learn how to map relevant regulatory requirements -- such as data-privacy or industry-specific rules -- directly onto the architecture, so compliance is designed in rather than checked at the end. The session also covers how to automate at least one compliance check, such as automatically verifying that data is encrypted, so evidence of compliance is collected continuously instead of scrambled together during an annual audit.", "Learning Type": "SPL", "Duration (Hrs)": "2", "Hands-on Activity": "Map relevant compliance requirements onto the Vantage Retail architecture and automate one control check as a continuous compliance safeguard.", "Learning Outcomes": "Compliance mapping and one automated control check for the Vantage Retail platform."}'),
	(81, 3, 31, 'Day 17', 'Case Lab: Secure Architecture Review', '{"Day": "Day 17", "Week": "Week 4", "Topic": "Case Lab: Secure Architecture Review", "Module": "Security & Compliance Engineering", "Sub Topic": "This is a consolidation session for the security workstream. Participants bring together the threat model, the zero-trust redesign and the compliance mapping into one complete secure-architecture review, and produce a prioritized roadmap listing which security gaps need to be fixed first and why -- the kind of document a security or compliance lead would expect to see before sign-off.", "Learning Type": "IL", "Duration (Hrs)": "2", "Hands-on Activity": "Consolidate the threat model, zero-trust design and compliance mapping from Sessions 1-3 into a full secure-architecture review of Vantage Retail, and present a remediation roadmap.", "Learning Outcomes": "Consolidated security package (v1), layered onto the cumulative Vantage Retail design."}'),
	(134, 5, 10, 'Day 3', 'Metrics, Logs, Traces & Correlation', '{"Day": "Day 3", "Week": "Week 1", "Topic": "Metrics, Logs, Traces & Correlation", "Module": "Observability & Monitoring", "Sub Topic": "Build the observability model for service health; correlate request metrics, structured logs and distributed traces to move from symptom to probable cause.", "Hands-on Labs": "Lab 1 – Observability Setup, Part A:\n• Instrument the Order API with request count, latency and error metrics.\n• Add structured request/error logs with correlation IDs.\n• Add trace propagation across Order → Payment.\n• Generate test traffic and correlate one slow transaction across metrics, logs and traces.", "Duration (Hrs)": "3.4333", "Learning Outcomes": "Instrumented service branch + sample correlated metric/log/trace evidence.", "Learning Type (SPL / IL)": "SPL"}'),
	(82, 3, 34, 'Day 19', 'Translating Architecture to Business Language & Influence Without Authority', '{"Day": "Day 19", "Week": "Week 4", "Topic": "Translating Architecture to Business Language & Influence Without Authority", "Module": "Business Translation & Leadership", "Sub Topic": "Participants learn how to explain technical decisions and trade-offs to non-technical stakeholders -- leadership, product managers, clients -- in language they can act on, without oversimplifying or losing important nuance. The session also covers how to negotiate for a technical priority, such as extra time to close a resilience gap, when the participant has no formal authority over the other team, through a realistic negotiation role-play.", "Learning Type": "IL", "Duration (Hrs)": "4", "Hands-on Activity": "Build a stakeholder pitch for the complete Vantage Retail platform — architecture, AI feature, cloud deployment and security posture — and rehearse a negotiation for one contested trade-off with a peer playing a resistant stakeholder.", "Learning Outcomes": "Stakeholder pitch deck and negotiation notes for the complete Vantage Retail platform."}'),
	(83, 3, 35, 'Day 20', 'Cost/ROI Framing & Change Leadership', '{"Day": "Day 20", "Week": "Week 4", "Topic": "Cost/ROI Framing & Change Leadership", "Module": "Business Translation & Leadership", "Sub Topic": "Participants learn how to present a technical decision in the terms the business cares about most -- cost and return on investment -- rather than purely technical merit. The session also covers change leadership: how to plan and sequence the rollout of a new platform or process in a way that anticipates resistance from the teams affected by the change, instead of assuming everyone will adopt it automatically.", "Learning Type": "SPL", "Duration (Hrs)": "2", "Hands-on Activity": "Build a cost/ROI one-pager for the Vantage Retail platform and a phased rollout plan for taking it into production.", "Learning Outcomes": "ROI one-pager and phased rollout plan for the Vantage Retail platform."}'),
	(84, 3, 36, 'Day 20', 'Build vs Buy & Vendor Evaluation', '{"Day": "Day 20", "Week": "Week 4", "Topic": "Build vs Buy & Vendor Evaluation", "Module": "Business Translation & Leadership", "Sub Topic": "Participants learn a structured framework for deciding whether to build a capability in-house or buy it from a vendor -- weighing cost, time-to-market, control and long-term maintenance -- instead of defaulting to whichever option the team is most comfortable with. The session also covers how to run a basic vendor evaluation, comparing options against the same criteria side by side.", "Learning Type": "SPL", "Duration (Hrs)": "2", "Hands-on Activity": "Apply a build-vs-buy scoring framework to one Vantage Retail component — the AI shopping-assistant vendor-vs-in-house decision — completing the Vantage Retail evidence pack.", "Learning Outcomes": "Build-vs-buy scorecard, completing the final version of the Vantage Retail evidence pack."}'),
	(85, 3, 40, 'Day 23', 'Capstone Day 1 — Architect the Platform', '{"Day": "Day 23", "Week": "Week 5", "Topic": "Capstone Day 1 — Architect the Platform", "Module": "Capstone Project", "Sub Topic": "Participants are introduced to a brand-new case study -- Solstice Health, a patient engagement platform covering appointment scheduling, records access, care-coordination messaging and notifications -- that they have not worked on before. Working independently and without step-by-step guidance, participants apply everything learned in the Architecture Foundations module: selecting an architecture pattern, defining NFRs, writing ADRs and producing a full distributed-system design, this time entirely on their own.", "Learning Type": "Capstone", "Duration (Hrs)": "4", "Hands-on Activity": "Independently architect the Solstice Health platform end to end: select an architecture pattern combination, define NFRs, write the supporting ADRs, and produce a distributed-system design for the core patient-engagement journey.", "Learning Outcomes": "Solstice Health architecture design package: pattern decision, NFR specification, ADR set and system design."}'),
	(86, 3, 41, 'Day 24', 'Capstone Day 2 — Integrate AI & Deploy to Cloud', '{"Day": "Day 24", "Week": "Week 5", "Topic": "Capstone Day 2 — Integrate AI & Deploy to Cloud", "Module": "Capstone Project", "Sub Topic": "Participants extend the architecture from Day 1 by designing an AI-powered care-coordination assistant for the platform, then take the resulting design and deploy it to the cloud -- designing the multi-service cloud layout and writing the Infrastructure-as-Code templates needed to stand it up. This applies the AI-integration and cloud-deployment skills from the program independently, without the step-by-step support given during the modules.", "Learning Type": "Capstone", "Duration (Hrs)": "4", "Hands-on Activity": "Design and integrate an AI-powered care-coordination assistant into the Day 1 architecture, then translate the resulting platform into a multi-service cloud design and an Infrastructure-as-Code deployment baseline.", "Learning Outcomes": "AI-integrated feature design and cloud deployment package for the Solstice Health platform."}'),
	(87, 3, 42, 'Day 25', 'Capstone Day 3 — Secure, Comply & Build the Business Case', '{"Day": "Day 25", "Week": "Week 5", "Topic": "Capstone Day 3 — Secure, Comply & Build the Business Case", "Module": "Capstone Project", "Sub Topic": "Participants secure the platform built on Days 1 and 2 -- threat-modeling it and mapping it against relevant compliance requirements -- and then build the stakeholder business case for taking it into production, including cost/ROI framing. This closes out the capstone build by applying the security and business-translation skills from the program independently.", "Learning Type": "Capstone", "Duration (Hrs)": "4", "Hands-on Activity": "Thread-model and secure the Solstice Health platform, map it against relevant compliance requirements, and build the stakeholder pitch and cost/ROI case for taking it into production.", "Learning Outcomes": "Security and compliance package plus stakeholder pitch and ROI case for the Solstice Health platform."}'),
	(88, 3, 43, 'Day 26', 'Capstone Evaluation & Panel Review', '{"Day": "Day 26", "Week": "Week 6", "Topic": "Capstone Evaluation & Panel Review", "Module": "Capstone Project", "Sub Topic": "Participants present the complete Solstice Health capstone -- covering architecture, AI integration, cloud deployment, security and the business case -- to a review panel made up of the trainer and, where available, a client-side stakeholder. Participants respond to panel questions and defend their design decisions, the same way they would in a real project sign-off or client review.", "Learning Type": "Panel Review", "Duration (Hrs)": "4", "Hands-on Activity": "Deliver an end-to-end walkthrough of the Solstice Health capstone to a panel (trainer and, where available, a client-side stakeholder); respond to panel questioning on architecture, AI-integration, cloud, security and business-case decisions.", "Learning Outcomes": "Panel-scored capstone evaluation, covering design command, trade-off articulation and completeness of the evidence pack."}'),
	(89, 4, 3, NULL, 'Pre-Assessment (Prerequisites)', '{"Week": "Pre-Program", "Topic": "Pre-Assessment (Prerequisites)", "Module": "Prerequisite Validation", "Sub Topic": "REST APIs / HTTP concepts, service-layer thinking\nVersion control, pipelines, build/deploy/artifacts\nStructure, styling, basic layout\nSyntax, functions, arrays/objects\nTest basics, breakpoint/log-based debugging\nArrays, objects, basic algorithms\nRequest/response shapes, manual API testing", "Duration (Hrs)": "2"}'),
	(91, 4, 6, 'Day 1', 'Spring Boot Fundamentals, REST Controllers, Dependency Injection', '{"Day": "Day 1", "Week": "Week 1", "Topic": "Spring Boot Fundamentals, REST Controllers, Dependency Injection", "Module": "Java Backend Development", "Sub Topic": "Spring Boot project structure, auto-configuration and starter dependencies\nSpring IoC container and dependency injection with @Component/@Service/@Repository/@Autowired\nBuilding REST controllers with @RestController, request mapping and path/query parameters\nRequest/response JSON serialization with Jackson\nLayered architecture: Controller-Service-Repository pattern\nConfiguration management with application.properties/yml and profiles\nException handling with @ControllerAdvice and custom error responses\nRunning and debugging a Spring Boot application locally Delivered as an Instructor-Led (IL) session because of its complexity, integration or coordination needs; the mentor also opens with a guided review of the preceding Self-Paced (SPL) day(s) and resolves learner queries from those days before moving into today''s live topic.", "Hands-on Labs": "Case Study – Spring Boot Fundamentals, REST Controllers, Dependency Injection\nInput: PulseCart backend requirements, the agreed data model and existing project baseline.\nImplement: Stand up a layered Spring Boot service and expose the PulseCart catalog endpoints using controllers, services and dependency injection.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant integration path.\nOutput: Working Spring Boot Fundamentals, REST Controllers, Dependency Injection increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "4", "Learning Outcomes": "Stand up a layered Spring Boot REST service and expose PulseCart catalog endpoints using controllers, services and dependency injection.", "Learning Type (SPL / IL)": "IL"}'),
	(92, 4, 7, 'Day 2', 'Relational Database Design & JPA Entity Modeling', '{"Day": "Day 2", "Week": "Week 1", "Topic": "Relational Database Design & JPA Entity Modeling", "Module": "Java Backend Development", "Sub Topic": "Relational database design fundamentals: tables, primary/foreign keys, normalization\nDesigning the catalog/cart/order schema for PulseCart (ERD-level thinking)\nJPA annotations for entity modeling (@Entity, @Id, @GeneratedValue, @Column)\nMapping one-to-many and many-to-many relationships between entities\nEmbeddable types and value objects for reusable field groups\nChoosing appropriate column types, constraints and indexes\nAuditing fields (created/updated timestamps) and soft-delete patterns\nReviewing the schema against expected query patterns before implementation", "Hands-on Labs": "Case Study – Relational Database Design & JPA Entity Modeling\nInput: PulseCart backend requirements, the agreed data model and existing project baseline.\nImplement: Design the relational schema for the PulseCart catalog/cart/order domain and model it as JPA entities with correct relationships.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant integration path.\nOutput: Working Relational Database Design & JPA Entity Modeling increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "4", "Learning Outcomes": "Design a normalized relational schema and model it correctly as JPA entities for the PulseCart domain.", "Learning Type (SPL / IL)": "SPL"}'),
	(93, 4, 8, 'Day 3', 'Spring Data JPA Repositories, Queries & Transactions', '{"Day": "Day 3", "Week": "Week 1", "Topic": "Spring Data JPA Repositories, Queries & Transactions", "Module": "Java Backend Development", "Sub Topic": "Spring Data JPA repositories and derived query methods\nCustom queries with JPQL and native @Query\nTransactions and @Transactional boundaries; propagation and isolation basics\nDatabase migrations with Flyway/Liquibase basics\nPagination and sorting for list endpoints\nMapping entities to DTOs for clean API contracts\nN+1 query detection and fetch-strategy tuning (lazy vs eager)\nValidating repository behavior against the PulseCart requirements", "Hands-on Labs": "Case Study – Spring Data JPA Repositories, Queries & Transactions\nInput: PulseCart backend requirements, the agreed data model and existing project baseline.\nImplement: Implement Spring Data JPA repositories, custom queries and migrations for the PulseCart catalog/cart/order domain, then expose paginated, DTO-mapped data.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant integration path.\nOutput: Working Spring Data JPA Repositories, Queries & Transactions increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "4", "Learning Outcomes": "Query, migrate and expose the PulseCart domain through Spring Data JPA repositories with clean DTO contracts.", "Learning Type (SPL / IL)": "SPL"}'),
	(94, 4, 9, 'Day 4', 'REST API Design, Validation, Service Layer Business Logic', '{"Day": "Day 4", "Week": "Week 1", "Topic": "REST API Design, Validation, Service Layer Business Logic", "Module": "Java Backend Development", "Sub Topic": "RESTful API design principles: resources, verbs and status codes\nRequest validation with Bean Validation (@Valid, @NotNull, custom validators)\nService-layer business logic separated from persistence and presentation\nDTO/mapper patterns for clean request/response contracts\nConsistent error contracts and problem-detail responses\nAPI versioning strategies\nDesigning endpoints for the PulseCart catalog/cart/order domain\nDocumenting APIs with OpenAPI/Swagger Delivered as an Instructor-Led (IL) session because of its complexity, integration or coordination needs; the mentor also opens with a guided review of the preceding Self-Paced (SPL) day(s) and resolves learner queries from those days before moving into today''s live topic.", "Hands-on Labs": "Case Study – REST API Design, Validation, Service Layer Business Logic\nInput: PulseCart backend requirements, the agreed data model and existing project baseline.\nImplement: Design validated catalog/cart/order endpoints with a clean service layer and OpenAPI documentation.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant integration path.\nOutput: Working REST API Design, Validation, Service Layer Business Logic increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "4", "Learning Outcomes": "Design validated, well-structured REST APIs with a clean service layer and documented contracts.", "Learning Type (SPL / IL)": "IL"}'),
	(135, 5, 11, 'Day 4', 'Prometheus, Grafana, Datadog, CloudWatch', '{"Day": "Day 4", "Week": "Week 1", "Topic": "Prometheus, Grafana, Datadog, CloudWatch", "Module": "Observability & Monitoring", "Sub Topic": "Configure collection, visualization and monitoring workflows across the approved observability stack; connect service telemetry to operational dashboards and alerts.", "Hands-on Labs": "Lab 1 – Observability Setup, Part B + Lab 2 – SLI/SLO & Alerting:\n• Collect metrics using Prometheus / Datadog.\n• Build Grafana service dashboard.\n• Use CloudWatch for AWS infrastructure signals.\n• Configure SLO-based warning/burn-rate alerts.\n• Validate alert firing using controlled degradation.", "Duration (Hrs)": "7.1333", "Learning Outcomes": "Grafana dashboard + Prometheus/Datadog monitor set + CloudWatch evidence + tested SLO alerts.", "Learning Type (SPL / IL)": "SPL"}'),
	(237, 6, 87, NULL, 'React Router and navigation', '{"Topic": "React Router and navigation", "Assessment Area": "React JS"}'),
	(95, 4, 10, 'Day 5', 'Spring Security Fundamentals & JWT Authentication', '{"Day": "Day 5", "Week": "Week 2", "Topic": "Spring Security Fundamentals & JWT Authentication", "Module": "Java Backend Development", "Sub Topic": "Spring Security filter chain and configuration fundamentals\nAuthentication providers and password encoding (BCrypt)\nBuilding a custom UserDetailsService for PulseCart accounts\nJWT structure, signing and stateless authentication for REST APIs\nIssuing and validating JWTs on login and subsequent requests\nRefresh-token concepts and expiry handling\nCORS configuration for Angular client consumption\nTesting authentication flows with Postman and automated tests", "Hands-on Labs": "Case Study – Spring Security Fundamentals & JWT Authentication\nInput: PulseCart backend requirements, the agreed data model and existing project baseline.\nImplement: Implement Spring Security with a custom UserDetailsService and JWT issuance/validation for the PulseCart login flow.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant integration path.\nOutput: Working Spring Security Fundamentals & JWT Authentication increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "4", "Learning Outcomes": "Implement JWT-based authentication for PulseCart using Spring Security.", "Learning Type (SPL / IL)": "SPL"}'),
	(96, 4, 11, 'Day 6', 'Authorization, Role-Based Access Control & API Security Hardening', '{"Day": "Day 6", "Week": "Week 2", "Topic": "Authorization, Role-Based Access Control & API Security Hardening", "Module": "Java Backend Development", "Sub Topic": "Role/claim-based authorization on endpoints (@PreAuthorize, method security)\nSecuring sensitive endpoints and restricting unauthorized operations\nDesigning role/permission models for the PulseCart account and order domain\nOAuth concepts and delegated authorization flow at a practical level\nHandling 401/403 responses consistently\nProtecting against common API security risks (mass assignment, over-fetching)\nSecurity-focused code review checklist for REST endpoints\nTesting authorization rules with both valid and invalid roles Delivered as an Instructor-Led (IL) session because of its complexity, integration or coordination needs; the mentor also opens with a guided review of the preceding Self-Paced (SPL) day(s) and resolves learner queries from those days before moving into today''s live topic.", "Hands-on Labs": "Case Study – Authorization, Role-Based Access Control & API Security Hardening\nInput: PulseCart backend requirements, the agreed data model and existing project baseline.\nImplement: Add role/claim-based authorization to account and order endpoints, then verify both authorized and unauthorized access paths.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant integration path.\nOutput: Working Authorization, Role-Based Access Control & API Security Hardening increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "4", "Learning Outcomes": "Enforce role-based authorization and harden PulseCart REST endpoints against common API security risks.", "Learning Type (SPL / IL)": "IL"}'),
	(97, 4, 12, 'Day 7', 'Testing & Data Access Hardening (JUnit, Mockito, Testcontainers)', '{"Day": "Day 7", "Week": "Week 2", "Topic": "Testing & Data Access Hardening (JUnit, Mockito, Testcontainers)", "Module": "Java Backend Development", "Sub Topic": "Unit testing services and controllers with JUnit 5 and Mockito\nIntegration testing with @SpringBootTest and MockMvc\nTesting repositories against an embedded/test database with Testcontainers\nMocking external dependencies and edge-case scenarios\nContract testing between the backend and the Angular client expectations\nLogging and structured error handling for observability\nPerformance basics: connection pooling and N+1 query detection\nValidating API behavior against the PulseCart requirements Delivered as an Instructor-Led (IL) session because of its complexity, integration or coordination needs; the mentor also opens with a guided review of the preceding Self-Paced (SPL) day(s) and resolves learner queries from those days before moving into today''s live topic.", "Hands-on Labs": "Case Study – Testing & Data Access Hardening (JUnit, Mockito, Testcontainers)\nInput: PulseCart backend requirements, the agreed data model and existing project baseline.\nImplement: Add JUnit/Mockito unit tests and MockMvc/Testcontainers integration tests for the catalog and order-tracking endpoints; capture before/after evidence.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant integration path.\nOutput: Working Testing & Data Access Hardening (JUnit, Mockito, Testcontainers) increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "4", "Learning Outcomes": "Harden the Spring Boot backend with unit, integration and contract-level tests.", "Learning Type (SPL / IL)": "IL"}'),
	(98, 4, 13, 'Day 8', 'Backend Service Consolidation & Layered Architecture Review', '{"Day": "Day 8", "Week": "Week 2", "Topic": "Backend Service Consolidation & Layered Architecture Review", "Module": "Java Backend Development", "Sub Topic": "Consolidating catalog, account, cart and order-tracking REST endpoints into one coherent Spring Boot service\nReviewing layered architecture consistency across all endpoints\nEnd-to-end request tracing from controller to repository\nFinalizing DTO contracts that the Angular client will consume\nReviewing security, validation and error-handling consistency\nPreparing a Postman collection / OpenAPI spec as the frontend contract\nDatabase schema review and migration consistency check\nReadiness check before frontend foundation sessions begin", "Hands-on Labs": "Case Study – Java Backend Journey Consolidation\nInput: Existing PulseCart controllers, services, repositories and entities from prior Java backend sessions.\nImplement: Consolidate the catalog, account, cart and order-tracking endpoints into one coherent, secured Spring Boot service.\nIntegrate: Combine persistence, validation, security and error handling into one consistent backend.\nValidate: Verify endpoint behavior, security enforcement, and DTO contract stability end-to-end.\nOutput: Consolidated, production-style Spring Boot backend ready to be consumed once the frontend foundation is complete.\nEvidence: Source code, Postman collection/OpenAPI spec, test results and short implementation note.", "Duration (Hrs)": "4", "Learning Outcomes": "Consolidate a complete Spring Boot backend journey with reusable controllers, services and repositories ready for frontend consumption.", "Learning Type (SPL / IL)": "SPL"}'),
	(99, 4, 14, 'Day 9', 'API Documentation & Contract Finalization for Frontend Consumption', '{"Day": "Day 9", "Week": "Week 2", "Topic": "API Documentation & Contract Finalization for Frontend Consumption", "Module": "Java Backend Development", "Sub Topic": "Finalizing OpenAPI/Swagger documentation for all PulseCart endpoints\nPublishing a stable REST contract for future Angular consumption\nSample request/response payload documentation\nBackward-compatible API evolution practices\nCORS and environment configuration for local frontend development\nPostman collection handoff and API smoke testing\nAligning error-response shapes with expected frontend error-handling behavior\nSign-off checklist before frontend foundation and Angular sessions", "Hands-on Labs": "Case Study – Backend Contract Finalization\nInput: The consolidated PulseCart Spring Boot backend and its OpenAPI/Postman documentation.\nImplement: Finalize and publish a stable, versioned REST contract with sample payloads and CORS configuration for future frontend consumption.\nIntegrate: Align error-response shapes and DTO contracts with the upcoming Foundation and Angular sessions.\nValidate: Smoke-test every endpoint via Postman and confirm the published contract matches actual behavior.\nOutput: A documented, stable Java REST API contract ready for frontend integration.\nEvidence: OpenAPI spec, Postman collection, smoke-test evidence and short implementation note.", "Duration (Hrs)": "4", "Learning Outcomes": "Finalize and document a stable Java REST API contract ready for frontend integration.", "Learning Type (SPL / IL)": "SPL"}'),
	(100, 4, 15, 'Day 10', 'Spring Security Deep-Dive & Method-Level Authorization', '{"Day": "Day 10", "Week": "Week 3", "Topic": "Spring Security Deep-Dive & Method-Level Authorization", "Module": "Java Backend Development", "Sub Topic": "Role-based and claim-based authorization beyond basic authentication\nMethod-level security (@PreAuthorize, @Secured) for fine-grained access control\nSecuring specific PulseCart operations (e.g. only an account owner can view their own orders)\nOAuth2 concepts: authorization code flow, resource server configuration (conceptual + practical basics)\nRefresh tokens and token expiry strategy beyond the Module 1 basics\nCommon security pitfalls in REST APIs (broken object-level authorization, over-permissive CORS)\nSecurity testing: verifying access-control rules with negative test cases", "Hands-on Labs": "Case Study – Spring Security Deep-Dive\nInput: The Module 1 PulseCart authentication layer (Day 6), the account/order domain.\nImplement: Add method-level authorization so a customer can only access their own PulseCart orders and account data; add a negative test proving cross-account access is rejected.\nIntegrate: Extends the Day 6 JWT authentication layer built earlier in this module – does not replace or alter the core backend used by Foundation/React/React Native.\nValidate: Attempt to access another customer''s order via the API and confirm it is correctly rejected; confirm the account owner''s own access still works.\nOutput: Fine-grained, object-level authorization on top of the Module 1 authentication layer.\nEvidence: Source code/configuration, a Postman run showing both the rejected and accepted access attempts, and a short implementation note.", "Duration (Hrs)": "4", "Learning Outcomes": "Apply method-level, object-level authorization correctly on top of a working authentication layer.", "Learning Type (SPL / IL)": "SPL"}'),
	(101, 4, 16, 'Day 11', 'Advanced Transactions – Propagation, Isolation, Distributed Consistency', '{"Day": "Day 11", "Week": "Week 3", "Topic": "Advanced Transactions – Propagation, Isolation, Distributed Consistency", "Module": "Java Backend Development", "Sub Topic": "@Transactional propagation behavior (REQUIRED, REQUIRES_NEW, NESTED) and when each applies\nIsolation levels (READ COMMITTED, REPEATABLE READ, SERIALIZABLE) and the race conditions they prevent\nDiagnosing and reproducing a lost-update/race-condition scenario\nDesigning a multi-step write (e.g. decrement stock + create order) for consistency under concurrent requests\nDistributed transaction concepts: why they''re hard across services, and the Saga pattern as a practical alternative\nCompensating actions as a substitute for distributed ACID transactions\nTesting transactional behavior under simulated concurrent load", "Hands-on Labs": "Case Study – Advanced Transactions\nInput: The Day 4 PulseCart order-placement flow, a simulated concurrent-order scenario.\nImplement: Reproduce a race condition on PulseCart stock decrement under concurrent order requests; fix it using correct transaction propagation/isolation; document a Saga-style compensating-action design for a hypothetical multi-service version of order placement.\nIntegrate: Builds on the Day 4 OrderService and Product/Order entities – the fix improves the same backend, it does not fork a separate one.\nValidate: Re-run the concurrent-order scenario after the fix and confirm the race condition no longer produces incorrect stock levels.\nOutput: A race-condition-safe order-placement flow, plus a documented Saga-pattern design note.\nEvidence: Source code/configuration, before/after test evidence of the race condition, the Saga design note, and a short implementation note.", "Duration (Hrs)": "4", "Learning Outcomes": "Diagnose and fix transactional race conditions, and reason about distributed-transaction alternatives like the Saga pattern.", "Learning Type (SPL / IL)": "SPL"}'),
	(102, 4, 17, 'Day 12', 'Event-Driven Programming – Messaging, Async Processing', '{"Day": "Day 12", "Week": "Week 3", "Topic": "Event-Driven Programming – Messaging, Async Processing", "Module": "Java Backend Development", "Sub Topic": "Publish-subscribe fundamentals and when event-driven design beats direct synchronous calls\nProducing and consuming messages with Kafka or RabbitMQ (either acceptable; pick one consistently)\nDesigning an event schema (e.g. OrderPlaced) that other services could consume\nAsync processing: decoupling a slow/non-critical step from the main request path\nAt-least-once delivery, idempotent consumers and basic failure handling for message processing\nObservability for event-driven flows (tracing an event from publish to consumption)\nWhere event-driven design fits alongside the REST API built earlier in this module (complementary, not a replacement)", "Hands-on Labs": "Case Study – Event-Driven Programming\nInput: The Day 4/Day 9 PulseCart order-placement flow, a message broker (Kafka or RabbitMQ) development instance.\nImplement: Publish an OrderPlaced event when a PulseCart order is created; build a simple consumer that reacts to it (e.g. logs a notification-ready record) asynchronously.\nIntegrate: Triggers from the same OrderService built on Day 4 – the REST API behavior for the caller is unchanged; the event is additive.\nValidate: Place an order and confirm the event is published and consumed correctly, including a check that the consumer handles a duplicate/redelivered message idempotently.\nOutput: An event-driven extension to the PulseCart order-placement flow.\nEvidence: Producer/consumer source code/configuration, evidence of a published and consumed event, and a short implementation note.", "Duration (Hrs)": "4", "Learning Outcomes": "Design and implement a basic event-driven extension to a REST API, including idempotent consumption.", "Learning Type (SPL / IL)": "SPL"}'),
	(103, 4, 21, 'Day 13', 'JavaScript (ES6+), TypeScript', '{"Day": "Day 13", "Week": "Week 3", "Topic": "JavaScript (ES6+), TypeScript", "Module": "Foundation", "Sub Topic": "JavaScript ES6+ syntax: let/const, template literals, destructuring, spread/rest and default parameters\nModules and reusable functions using import/export\nArrays and objects: map/filter/reduce, immutable update patterns and object transformation\nTypeScript primitives, arrays, tuples, enums, unions and literal types\nInterfaces vs type aliases; optional/readonly properties and reusable domain models\nTyped functions, return types, callbacks and basic generic usage\nType narrowing, null/undefined handling and compile-time error interpretation\nOrganizing typed frontend code for maintainability and API consumption", "Hands-on Labs": "Case Study – JavaScript (ES6+), TypeScript\nInput: PulseCart foundation requirements, sample API payloads and existing project baseline.\nImplement: Create typed product, cart and customer models plus reusable transformation/validation utilities for the PulseCart data set.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant web/mobile/integration path.\nOutput: Working JavaScript (ES6+), TypeScript increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "5", "Learning Outcomes": "Use modern JavaScript and TypeScript safely to model and manipulate application data.", "Learning Type (SPL / IL)": "SPL"}'),
	(136, 5, 14, 'Day 5', 'AWS Core Services', '{"Day": "Day 5", "Week": "Week 1", "Topic": "AWS Core Services", "Module": "Cloud & Infrastructure", "Sub Topic": "Apply EC2, S3, VPC, IAM, RDS, ELB/ALB and CloudWatch fundamentals to a reliability-oriented service architecture, including scaling and resilience considerations.", "Hands-on Labs": "Lab 3 – Infrastructure as Code, Part A:\n• Map RetailPulse components to VPC, ALB, compute, RDS, S3, IAM and CloudWatch.\n• Define availability-zone placement and traffic path.\n• Capture infrastructure dependencies and failure domains before provisioning.", "Duration (Hrs)": "6.7333", "Learning Outcomes": "AWS reliability architecture diagram + dependency/failure-domain map.", "Learning Type (SPL / IL)": "SPL"}'),
	(238, 6, 88, NULL, 'State management (Redux / Redux Toolkit basics)', '{"Topic": "State management (Redux / Redux Toolkit basics)", "Assessment Area": "React JS"}'),
	(104, 4, 22, 'Day 14', 'HTML5, CSS3, Responsive Design', '{"Day": "Day 14", "Week": "Week 3", "Topic": "HTML5, CSS3, Responsive Design", "Module": "Foundation", "Sub Topic": "Semantic HTML5 structure for application pages, sections, navigation, forms and reusable content blocks\nForm elements, labels, input types and browser-native validation fundamentals\nCSS cascade, specificity, inheritance, box model and layout troubleshooting\nFlexbox and CSS Grid for application layouts\nResponsive design using fluid sizing, media queries and breakpoint strategy\nMobile-first and desktop-adaptive layout techniques\nReusable styling conventions for states, spacing, typography and components\nCross-device validation for desktop, tablet and mobile viewports", "Hands-on Labs": "Case Study – HTML5, CSS3, Responsive Design\nInput: PulseCart foundation requirements, sample API payloads and existing project baseline.\nImplement: Build a responsive catalog/product-detail shell that works across desktop, tablet and narrow mobile web widths.\nIntegrate: Reuse the same catalog, account, cart and order-tracking journey components/contracts already built in prior sessions.\nValidate: Run the feature, verify expected success/failure behavior and check the relevant web/mobile/integration path.\nOutput: Working HTML5, CSS3, Responsive Design increment integrated into the continuous PulseCart OneJourney solution.\nEvidence: Source code/configuration, screenshots or test output, and a short implementation note.", "Duration (Hrs)": "4", "Learning Outcomes": "Create semantic, responsive interfaces that remain usable across common viewport sizes.", "Learning Type (SPL / IL)": "SPL"}'),
