	(285, 9, 7, 'Day 0', 'Pre-Assessment (2 hrs): baseline skill check (programming fundamentals + aptitude), used to validate track placement readiness.  ·  AI Tool Orientation (2 hrs): GitHub Copilot (personal productivity) setup/walkthrough + AWS Q Developer & enterprise GenAI tooling overview + prompt-engineering basics — the toolchain used throughout the programme.', '{"Week": "Day 0", "Total": "4*", "Module": "Pre-Assessment + AI Tool Orientation", "Prereq": "None — entry point", "Date Range": "Before Wk 1", "Hrs (L·H·A)": "2·2·0", "Table of Content": "Pre-Assessment (2 hrs): baseline skill check (programming fundamentals + aptitude), used to validate track placement readiness.  ·  AI Tool Orientation (2 hrs): GitHub Copilot (personal productivity) setup/walkthrough + AWS Q Developer & enterprise GenAI tooling overview + prompt-engineering basics — the toolchain used throughout the programme.", "Learning Outcomes": "Establish baseline readiness + shared AI toolchain familiarity", "Hands-on Activities": "—", "AI Integration Point": "AI Tool Orientation (GitHub Copilot — personal productivity; AWS Q Developer & LangChain/RAG tooling — capstone/infra overview)"}'),
	(286, 9, 10, 'Wk 1–2', 'Java setup/IDE; variables & types; control flow; collections; exceptions; OOP (classes, encapsulation, inheritance, polymorphism)', '{"Week": "Wk 1–2", "Total": "80", "Module": "Core Java & OOP", "Prereq": "None — entry module", "Date Range": "27 Jul – 07 Aug 26", "Hrs (L·H·A)": "20·36·24", "Table of Content": "Java setup/IDE; variables & types; control flow; collections; exceptions; OOP (classes, encapsulation, inheritance, polymorphism)", "Learning Outcomes": "Set up Java dev environment; apply OOP fundamentals independently", "Hands-on Activities": "Console calculator; menu-driven app; contact book; custom exception; domain classes; OOP refactors", "AI Integration Point": "Copilot code completion in IDE setup; AI-generated OOP concept explanations (personal productivity)"}'),
	(287, 9, 14, 'Wk 3', 'Components, props, state, events; hooks (useState/useEffect), Context API; routing; consuming REST APIs; build & deployment basics', '{"Week": "Wk 3", "Total": "40", "Module": "React (Frontend) Essentials", "Prereq": "None — parallel foundational skill", "Date Range": "10 Aug – 14 Aug 26", "Hrs (L·H·A)": "10·20·10", "Table of Content": "Components, props, state, events; hooks (useState/useEffect), Context API; routing; consuming REST APIs; build & deployment basics", "Learning Outcomes": "Build a responsive React frontend and consume a REST API — completing the full-stack loop with the Spring Boot service built later in the track", "Hands-on Activities": "Build interactive UI components; hooks-based state management; React Router navigation; fetch/axios API consumption against a mock endpoint; production build", "AI Integration Point": "Copilot component scaffolding; AI-assisted debugging (personal productivity)"}'),
