	(370, 14, 9, NULL, 'Agile / Scrum Ceremonies + Sprint Simulation', '{"Phase": "Phase 1 — Foundations", "Topic": "Agile / Scrum Ceremonies + Sprint Simulation", "Sub-Topic": "Sprint planning, daily stand-up, retro, sprint artifacts (backlog, burndown)", "Phase / Module": "SDLC & Agile Methodology", "Learning Format": "Self-paced Video + Embedded Assignment", "Learning Outcome": "Learner can explain Scrum ceremonies/artifacts and prioritize/size backlog items into a sprint", "Artefact(s) Produced": "Sprint backlog board (exported screenshot/JSON)", "Video / Content (hrs)": "1", "Assignment / Hands-on (hrs)": "0.25", "Assignment(s) — realistic time incl. buffer": "A1 (20 min): Groom the provided 12-item Mphasis Digital Lending Platform backlog (loan application, KYC verification, approval workflow) using MoSCoW prioritization and plan Sprint 1 against a 10-story-point capacity."}'),
	(371, 14, 10, NULL, 'Knowledge Check', '{"Phase": "Phase 1 — Foundations", "Topic": "Knowledge Check", "Sub-Topic": "SDLC stages & Agile terminology", "Phase / Module": "SDLC & Agile Methodology", "Learning Format": "Auto-graded MCQ", "Learning Outcome": "Validated baseline understanding of SDLC/Agile concepts", "Milestone / Gate": "Gate 1a — pass to proceed", "Artefact(s) Produced": "MCQ score report", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "0.5", "Assignment(s) — realistic time incl. buffer": "Assessment scope: SDLC stage identification, Agile ceremony purpose, artifact terminology"}'),
	(372, 14, 12, NULL, 'Version Control Concepts + Repo Setup', '{"Phase": "Phase 1 — Foundations", "Topic": "Version Control Concepts + Repo Setup", "Sub-Topic": "Why version control, repo structure, local vs remote, staging area & .gitignore, remote tracking branches", "Phase / Module": "Git Essentials", "Learning Format": "Self-paced Video + Embedded Assignments", "Learning Outcome": "Learner understands version control fundamentals and can independently set up/commit to a repo", "Artefact(s) Produced": "Repo with initial commit + cloned working copy (auto-captured)", "Video / Content (hrs)": "1", "Assignment / Hands-on (hrs)": "0.25", "Assignment(s) — realistic time incl. buffer": "A1 (10 min): Initialize a local Git repository named ''loan-eligibility-service'', add the provided starter code skeleton, and make your first commit with a properly formatted commit message.\nA2 (10 min): Clone the shared ''loan-platform-common'' remote repository and verify your local working copy matches the remote HEAD."}'),
	(373, 14, 13, NULL, 'Branching & Merge Strategy + Conflict Resolution', '{"Phase": "Phase 1 — Foundations", "Topic": "Branching & Merge Strategy + Conflict Resolution", "Sub-Topic": "Branching models, fast-forward vs 3-way merge, rebase vs merge trade-offs, PR review etiquette", "Phase / Module": "Git Essentials", "Learning Format": "Self-paced Video + Embedded Assignments", "Learning Outcome": "Learner can choose the correct branch/merge strategy and resolve real merge conflicts independently", "Artefact(s) Produced": "Final repo state (commit graph, auto-validated)", "Video / Content (hrs)": "0.5", "Assignment / Hands-on (hrs)": "0.5", "Assignment(s) — realistic time incl. buffer": "A1 (15 min): Create feature branch ''feature/interest-rate-calc'', add a stub interest-rate-calculation method, and merge it back to main via a clean PR workflow.\nA2 (20 min): Resolve a seeded merge conflict between two parallel feature branches that both modify ''eligibility-rules.txt'', preserving both teams'' intended changes."}'),
	(374, 14, 14, NULL, 'Knowledge Check', '{"Phase": "Phase 1 — Foundations", "Topic": "Knowledge Check", "Sub-Topic": "Auto-graded CLI validation of repo state", "Phase / Module": "Git Essentials", "Learning Format": "Auto-graded CLI Check", "Learning Outcome": "Validated competency in core Git workflow", "Milestone / Gate": "Gate 1b — pass to proceed", "Artefact(s) Produced": "CLI assessment report", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "0.5", "Assignment(s) — realistic time incl. buffer": "Assessment scope: validates final repo/commit/branch state against expected configuration"}'),
	(375, 14, 16, NULL, 'RDBMS Concepts + Normalization Check', '{"Phase": "Phase 1 — Foundations", "Topic": "RDBMS Concepts + Normalization Check", "Sub-Topic": "Tables, relationships, normalization (1NF–3NF), entity vs attribute vs relationship, functional dependency basics", "Phase / Module": "Database Fundamentals", "Learning Format": "Self-paced Video + Embedded Assignment", "Learning Outcome": "Learner can explain normalization and justify schema design choices", "Video / Content (hrs)": "1", "Assignment / Hands-on (hrs)": "0.25", "Assignment(s) — realistic time incl. buffer": "A1 (15 min): Identify and correct 2 normalization violations in a provided flawed Mphasis customer-loan schema (denormalize spotted, fix to 3NF)."}'),
	(376, 14, 17, NULL, 'ER Modeling & Constraints + Schema Design Lab', '{"Phase": "Phase 1 — Foundations", "Topic": "ER Modeling & Constraints + Schema Design Lab", "Sub-Topic": "ER diagrams, primary/foreign keys, constraints, cardinality (1:1, 1:N, N:M), referential integrity", "Phase / Module": "Database Fundamentals", "Learning Format": "Self-paced Video + Embedded Assignments", "Learning Outcome": "Learner can independently design a normalized relational schema and ER diagram", "Artefact(s) Produced": "ER diagram (exported PNG/JSON)", "Video / Content (hrs)": "1", "Assignment / Hands-on (hrs)": "0.5", "Assignment(s) — realistic time incl. buffer": "A1 (20 min): Design an ER diagram for the ''Customer'' and ''LoanApplication'' entities with correct PK/FK relationships.\nA2 (15 min): Extend the diagram to add ''CollateralDetails'' and ''ApprovalStatus'' entities with correct relationships to the existing entities."}'),
	(377, 14, 18, NULL, 'Knowledge Check', '{"Phase": "Phase 1 — Foundations", "Topic": "Knowledge Check", "Sub-Topic": "MCQ + short scenario questions", "Phase / Module": "Database Fundamentals", "Learning Format": "Auto-graded MCQ + Scenario", "Learning Outcome": "Validated understanding of relational data modeling", "Milestone / Gate": "Gate 1c — pass to proceed", "Artefact(s) Produced": "Assessment score report", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "0.5", "Assignment(s) — realistic time incl. buffer": "Assessment scope: normalization rules, key/constraint identification, schema-design judgment"}'),
	(378, 14, 20, NULL, 'SQL Syntax — DDL & DML + Schema Build Lab', '{"Phase": "Phase 1 — Foundations", "Topic": "SQL Syntax — DDL & DML + Schema Build Lab", "Sub-Topic": "CREATE/ALTER/DROP, INSERT/UPDATE/DELETE/SELECT, constraints (NOT NULL/UNIQUE/CHECK), auto-increment/primary key", "Phase / Module": "MySQL", "Learning Format": "Self-paced Video + Embedded Assignments", "Learning Outcome": "Learner can write production-quality schema-definition and data-manipulation SQL", "Artefact(s) Produced": "Schema DDL + seeded dataset (auto-captured)", "Video / Content (hrs)": "1", "Assignment / Hands-on (hrs)": "0.75", "Assignment(s) — realistic time incl. buffer": "A1 (10 min): Write DDL to create the ''customers'' table with appropriate constraints.\nA2 (10 min): Write DDL to create the ''loan_applications'' table with a foreign key to ''customers''.\nA3 (15 min): Write DDL to create the ''repayments'' table with a foreign key to ''loan_applications'' plus an index on ''due_date''.\nA4 (10 min): Write INSERT/UPDATE statements to seed 5 sample loan records and update one repayment status."}'),
	(379, 14, 21, NULL, 'Joins, Subqueries & Indexing + Query Lab', '{"Phase": "Phase 1 — Foundations", "Topic": "Joins, Subqueries & Indexing + Query Lab", "Sub-Topic": "Inner/outer joins, correlated vs non-correlated subqueries, index design basics, composite index strategy", "Phase / Module": "MySQL", "Learning Format": "Self-paced Video + Embedded Assignments", "Learning Outcome": "Learner can write multi-table queries and reason about index usage", "Artefact(s) Produced": "Query log + output set (auto-captured)", "Video / Content (hrs)": "1", "Assignment / Hands-on (hrs)": "0.5", "Assignment(s) — realistic time incl. buffer": "A1 (15 min): Write a query listing all loan applications pending approval for more than 30 days using JOIN.\nA2 (20 min): Write a query calculating total disbursed amount per branch using JOIN, GROUP BY, and a subquery to flag the top-performing branch."}'),
	(380, 14, 22, NULL, 'Knowledge Check', '{"Phase": "Phase 1 — Foundations", "Topic": "Knowledge Check", "Sub-Topic": "Auto-graded SQL assessment (output validated)", "Phase / Module": "MySQL", "Learning Format": "Auto-graded SQL Coding Assessment", "Learning Outcome": "Validated SQL competency against expected result sets", "Milestone / Gate": "MILESTONE 1 — Foundations Gate: all 4 Phase 1 checks passed -> unlocks Phase 2", "Artefact(s) Produced": "SQL assessment report", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "1", "Assignment(s) — realistic time incl. buffer": "Assessment scope: query writing against the loan-platform dataset, output validated against expected result sets"}'),
	(381, 14, 24, NULL, 'Java Fundamentals + OOP Design Lab', '{"Phase": "Phase 2 — Core Development", "Topic": "Java Fundamentals + OOP Design Lab", "Sub-Topic": "Syntax, data types, control flow, OOP (classes, inheritance, polymorphism), static vs instance members, access modifiers, method overloading", "Phase / Module": "Core Java", "Learning Format": "Self-paced Video + Embedded Assignments", "Learning Outcome": "Learner can write a correctly structured OOP Java program", "Artefact(s) Produced": "Java source files (compiled, auto-validated)", "Video / Content (hrs)": "3", "Assignment / Hands-on (hrs)": "1", "Assignment(s) — realistic time incl. buffer": "A1 (15 min): Define a ''LoanApplicant'' class with fields (panNumber, monthlyIncome, cibilScore, existingEMI) and appropriate constructors.\nA2 (20 min): Implement inheritance: create ''SalariedApplicant'' and ''SelfEmployedApplicant'' subclasses, each overriding an ''incomeProofType()'' method.\nA3 (15 min): Add a ''toString()'' override and ''equals()''/''hashCode()'' to ''LoanApplicant'' supporting list de-duplication.\nA4 (10 min): Write a small driver class instantiating 3 applicants and printing their details via polymorphic method calls."}'),
	(382, 14, 25, NULL, 'Collections, Exceptions & File Handling + Applied Lab', '{"Phase": "Phase 2 — Core Development", "Topic": "Collections, Exceptions & File Handling + Applied Lab", "Sub-Topic": "List/Map/Set, Iterator, try-catch-finally, custom exceptions, file I/O, try-with-resources", "Phase / Module": "Core Java", "Learning Format": "Self-paced Video + Embedded Assignments", "Learning Outcome": "Learner can apply collections, custom exception handling, and file I/O in real code", "Artefact(s) Produced": "Java source files (compiled, auto-validated)", "Video / Content (hrs)": "3", "Assignment / Hands-on (hrs)": "1", "Assignment(s) — realistic time incl. buffer": "A1 (10 min): Store a batch of ''LoanApplicant'' objects in an ArrayList and filter applicants with cibilScore < 650 using a loop.\nA2 (15 min): Implement custom exception ''InvalidApplicantDataException'', thrown when income <= 0; handle via try-catch.\nA3 (15 min): Implement custom exception ''IneligibleApplicantException'', thrown when EMI ratio > 50%; handle within a batch loop without halting processing.\nA4 (20 min): Read a CSV of 5 applicants from file, parse into ''LoanApplicant'' objects, and write eligible ones to an output file."}'),
	(383, 14, 26, NULL, 'Applied Coding Lab — Loan Eligibility Engine', '{"Phase": "Phase 2 — Core Development", "Topic": "Applied Coding Lab — Loan Eligibility Engine", "Sub-Topic": "Integrated coding lab combining OOP, collections, and exception handling into one working module", "Phase / Module": "Core Java", "Learning Format": "Embedded Assignments (code editor + compiler)", "Learning Outcome": "Learner can independently design and implement a working, integrated Java module", "Artefact(s) Produced": "LoanEligibilityChecker module (compiled, auto-validated)", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "1", "Assignment(s) — realistic time incl. buffer": "A1 (20 min): Implement ''LoanEligibilityChecker.calculateRiskBand()'' combining CIBIL score and EMI ratio into Low/Medium/High risk bands.\nA2 (15 min): Implement ''checkExistingExposure()'' validating against a max-exposure threshold per applicant category.\nA3 (15 min): Integrate exception handling so a batch run of 10 applicants completes even if 2 throw exceptions, logging failures separately.\nA4 (10 min): Write a Java ''main()'' method that processes the batch end-to-end and prints a summary eligibility report."}'),
	(384, 14, 27, NULL, 'Unit Testing & Build Management', '{"Phase": "Phase 2 — Core Development", "Topic": "Unit Testing & Build Management", "Sub-Topic": "JUnit test structure, assertion types, test fixtures (@Before/@After), Maven dependency management & build lifecycle phases (compile/test/package)", "Phase / Module": "JUnit & Maven", "Learning Format": "Self-paced Video + Embedded Assignments", "Learning Outcome": "Learner can write meaningful unit tests and execute a Maven build end-to-end", "Artefact(s) Produced": "JUnit test suite + Maven build log", "Video / Content (hrs)": "0.5", "Assignment / Hands-on (hrs)": "1", "Assignment(s) — realistic time incl. buffer": "A1 (20 min): Write JUnit tests (min. 3 cases) covering boundary values for ''calculateRiskBand()''.\nA2 (20 min): Write JUnit tests (min. 3 cases) covering exception scenarios (invalid data, ineligible applicant).\nA3 (15 min): Configure a Maven ''pom.xml'' with required dependencies and execute ''mvn test'', validating all tests pass in the build."}'),
	(385, 14, 28, NULL, 'Knowledge Check', '{"Phase": "Phase 2 — Core Development", "Topic": "Knowledge Check", "Sub-Topic": "Auto-graded coding assessment (compile + test-pass validation)", "Phase / Module": "Core Java, JUnit & Maven", "Learning Format": "Auto-graded Coding Assessment", "Learning Outcome": "Validated competency in Java + unit testing + build tooling", "Milestone / Gate": "MILESTONE 2 — Core Development Gate: check passed -> unlocks Phase 3", "Artefact(s) Produced": "Compile/test execution report", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "2", "Assignment(s) — realistic time incl. buffer": "Assessment scope: independent coding task scored on compile success + test-pass rate"}'),
	(386, 14, 30, NULL, 'Semantic HTML & Layout + Structure Assignment', '{"Phase": "Phase 3 — Web & Scripting", "Topic": "Semantic HTML & Layout + Structure Assignment", "Sub-Topic": "Semantic tags, ARIA basics, CSS box model & specificity, flexbox/grid, mobile-first responsive breakpoints", "Phase / Module": "HTML5 & CSS3", "Learning Format": "Self-paced Video + Embedded Assignment", "Learning Outcome": "Learner can build semantically correct, responsive page structures", "Video / Content (hrs)": "2", "Assignment / Hands-on (hrs)": "0.25", "Assignment(s) — realistic time incl. buffer": "A1 (15 min): Build a semantic HTML skeleton (header/nav/main/footer) for the ''Loan Application — Step 1'' page using correct landmark tags."}'),
	(387, 14, 31, NULL, 'Build-a-Page Lab — Loan Application UI', '{"Phase": "Phase 3 — Web & Scripting", "Topic": "Build-a-Page Lab — Loan Application UI", "Sub-Topic": "Replicate the provided ''Loan Application — Step 1'' mockup using CSS3 layout techniques", "Phase / Module": "HTML5 & CSS3", "Learning Format": "Embedded Assignments (code editor + live preview)", "Learning Outcome": "Learner can translate a visual design into working, responsive markup/styling", "Artefact(s) Produced": "HTML/CSS files (rendered output, auto-validated)", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "1", "Assignment(s) — realistic time incl. buffer": "A1 (15 min): Style the applicant-details form using CSS flexbox for field alignment.\nA2 (15 min): Implement a responsive 2-column -> 1-column layout breakpoint at 768px using CSS Grid/media query.\nA3 (10 min): Style form validation states (error border/helper text) to match the provided mockup.\nA4 (15 min): Add a sticky progress-stepper header showing ''Step 1 of 3'' matching the mockup."}'),
	(388, 14, 32, NULL, 'Knowledge Check', '{"Phase": "Phase 3 — Web & Scripting", "Topic": "Knowledge Check", "Sub-Topic": "Auto-graded markup/style validation + MCQ", "Phase / Module": "HTML5 & CSS3", "Learning Format": "Auto-graded Assessment", "Learning Outcome": "Validated front-end markup/styling competency", "Milestone / Gate": "Gate 3a — pass to proceed", "Artefact(s) Produced": "Validation + MCQ report", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "0.5", "Assignment(s) — realistic time incl. buffer": "Assessment scope: DOM/CSS structure validation against reference layout + MCQ on responsive design concepts"}'),
	(389, 14, 34, NULL, 'JS Fundamentals & ES6 Features + Validation Assignments', '{"Phase": "Phase 3 — Web & Scripting", "Topic": "JS Fundamentals & ES6 Features + Validation Assignments", "Sub-Topic": "let/const, arrow functions, template literals, spread/rest operators, scope & closures, promises, destructuring", "Phase / Module": "JavaScript (ES6)", "Learning Format": "Self-paced Video + Embedded Assignments", "Learning Outcome": "Learner can write modern, idiomatic ES6 JavaScript", "Video / Content (hrs)": "2.5", "Assignment / Hands-on (hrs)": "0.5", "Assignment(s) — realistic time incl. buffer": "A1 (15 min): Implement PAN-format validation (regex) using arrow functions on the loan application form.\nA2 (10 min): Implement mobile-number validation using destructured input parsing."}'),
	(390, 14, 35, NULL, 'DOM & Async Logic Lab', '{"Phase": "Phase 3 — Web & Scripting", "Topic": "DOM & Async Logic Lab", "Sub-Topic": "DOM manipulation and Promise-based async handling on the loan application form", "Phase / Module": "JavaScript (ES6)", "Learning Format": "Embedded Assignments (code editor + live preview)", "Learning Outcome": "Learner can manipulate the DOM and implement async client-side logic independently", "Artefact(s) Produced": "JS source files (auto-validated output)", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "0.75", "Assignment(s) — realistic time incl. buffer": "A1 (15 min): Implement EMI auto-calculation that updates live as the applicant types loan amount/tenure.\nA2 (15 min): Use a Promise to simulate an async ''CIBIL score check'' API call (resolve/reject after a delay).\nA3 (10 min): Update the UI to show a loading spinner while the simulated API call is pending.\nA4 (10 min): Handle the API failure case (reject) by displaying an inline error message without breaking the form."}'),
	(391, 14, 36, NULL, 'Knowledge Check', '{"Phase": "Phase 3 — Web & Scripting", "Topic": "Knowledge Check", "Sub-Topic": "Auto-graded coding assessment", "Phase / Module": "JavaScript (ES6)", "Learning Format": "Auto-graded Coding Assessment", "Learning Outcome": "Validated JavaScript/ES6 competency", "Milestone / Gate": "Gate 3b — pass to proceed", "Artefact(s) Produced": "Coding assessment report", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "0.5", "Assignment(s) — realistic time incl. buffer": "Assessment scope: independent DOM/logic coding task scored on functional output"}'),
	(392, 14, 38, NULL, 'Types, Interfaces & Generics', '{"Phase": "Phase 3 — Web & Scripting", "Topic": "Types, Interfaces & Generics", "Sub-Topic": "Static typing, interfaces, generics, union/intersection types, type narrowing, tsconfig basics, TS vs JS trade-offs", "Phase / Module": "TypeScript", "Learning Format": "Self-paced Video", "Learning Outcome": "Learner understands when and why to use TypeScript over JS", "Video / Content (hrs)": "1.5", "Assignment / Hands-on (hrs)": "0"}'),
	(393, 14, 39, NULL, 'JS-to-TS Conversion Lab', '{"Phase": "Phase 3 — Web & Scripting", "Topic": "JS-to-TS Conversion Lab", "Sub-Topic": "Convert the JS loan-eligibility/validation modules into type-safe TS", "Phase / Module": "TypeScript", "Learning Format": "Embedded Assignments (code editor)", "Learning Outcome": "Learner can retrofit type safety onto existing JavaScript code", "Artefact(s) Produced": "TS files (compiler-validated, zero type errors)", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "0.75", "Assignment(s) — realistic time incl. buffer": "A1 (10 min): Define an ''Applicant'' interface with correctly typed fields (string/number).\nA2 (10 min): Define an ''EligibilityResult'' interface with a status: ''approved'' | ''referred'' | ''rejected'' union type.\nA3 (15 min): Convert the PAN/mobile validation functions (from the JS lab) into typed TS functions, fixing compiler errors.\nA4 (15 min): Convert the EMI-calculation function into a type-safe TS function and verify zero type errors on build."}'),
	(394, 14, 40, NULL, 'Knowledge Check', '{"Phase": "Phase 3 — Web & Scripting", "Topic": "Knowledge Check", "Sub-Topic": "Auto-graded coding assessment", "Phase / Module": "TypeScript", "Learning Format": "Auto-graded Coding Assessment", "Learning Outcome": "Validated TypeScript competency", "Milestone / Gate": "MILESTONE 3 — Web & Scripting Gate: all 3 Phase 3 checks passed -> unlocks Phase 4", "Artefact(s) Produced": "Coding assessment report", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "0.5", "Assignment(s) — realistic time incl. buffer": "Assessment scope: independent TS conversion/typing task scored on compiler validation"}'),
	(395, 14, 42, NULL, 'WebDriver Architecture & Locators + Step-1 Automation', '{"Phase": "Phase 4 — Test Automation", "Topic": "WebDriver Architecture & Locators + Step-1 Automation", "Sub-Topic": "WebDriver architecture, locator strategies, implicit vs explicit vs fluent waits, Actions class for complex interactions", "Phase / Module": "Selenium", "Learning Format": "Self-paced Video + Embedded Assignments", "Learning Outcome": "Learner can select reliable locator/wait strategies and automate a single UI step", "Artefact(s) Produced": "Automation script (Step 1, auto-captured)", "Video / Content (hrs)": "1.5", "Assignment / Hands-on (hrs)": "1", "Assignment(s) — realistic time incl. buffer": "A1 (15 min): Identify and write robust locators (ID/CSS/XPath) for the 5 key fields on the Applicant Details page.\nA2 (15 min): Implement explicit-wait handling for the asynchronous CIBIL-score-check loading spinner.\nA3 (20 min): Automate filling and submitting the Applicant Details step (Step 1) end-to-end.\nA4 (10 min): Add an assertion verifying navigation to Step 2 (Income Details) after successful submission."}'),
	(396, 14, 43, NULL, 'Page Object Model + POM Build-Out', '{"Phase": "Phase 4 — Test Automation", "Topic": "Page Object Model + POM Build-Out", "Sub-Topic": "POM design pattern for maintainable automation suites, base page class pattern, separating locators from test logic", "Phase / Module": "Selenium", "Learning Format": "Self-paced Video + Embedded Assignments", "Learning Outcome": "Learner can structure automation code using the POM pattern across a multi-step flow", "Artefact(s) Produced": "POM class files (auto-validated)", "Video / Content (hrs)": "1.5", "Assignment / Hands-on (hrs)": "1", "Assignment(s) — realistic time incl. buffer": "A1 (15 min): Build an ''ApplicantDetailsPage'' POM class encapsulating Step 1 locators and actions.\nA2 (15 min): Build an ''IncomeDetailsPage'' POM class encapsulating Step 2 locators and actions.\nA3 (20 min): Build a ''DocumentUploadPage'' POM class encapsulating Step 3 locators and the file-upload action.\nA4 (15 min): Wire the 3 POM classes together in a single test orchestrating Steps 1 -> 3 sequentially."}'),
	(397, 14, 44, NULL, 'Automation Lab — Full Flow Execution', '{"Phase": "Phase 4 — Test Automation", "Topic": "Automation Lab — Full Flow Execution", "Sub-Topic": "End-to-end execution and negative-path testing against the sandbox app", "Phase / Module": "Selenium", "Learning Format": "Embedded Assignments (automation sandbox + browser)", "Learning Outcome": "Learner can independently automate and validate a multi-step web user flow end-to-end", "Artefact(s) Produced": "Automation script + execution report (auto-captured)", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "0.5", "Assignment(s) — realistic time incl. buffer": "A1 (15 min): Execute the full 3-step automation against the sandbox app and capture a pass/fail execution report.\nA2 (15 min): Introduce a deliberate locator break and verify the suite fails gracefully with a clear error message (negative test)."}'),
	(398, 14, 45, NULL, 'Knowledge Check', '{"Phase": "Phase 4 — Test Automation", "Topic": "Knowledge Check", "Sub-Topic": "Auto-graded script execution assessment", "Phase / Module": "Selenium", "Learning Format": "Auto-graded Coding Assessment", "Learning Outcome": "Validated Selenium automation competency", "Milestone / Gate": "Gate 4a — pass to proceed", "Artefact(s) Produced": "Script execution report", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "1", "Assignment(s) — realistic time incl. buffer": "Assessment scope: independent automation task scored on script execution success against sandbox app"}'),
	(399, 14, 47, NULL, 'BDD Concepts & Gherkin Syntax + Scenario Drafting', '{"Phase": "Phase 4 — Test Automation", "Topic": "BDD Concepts & Gherkin Syntax + Scenario Drafting", "Sub-Topic": "BDD principles, Gherkin (Given/When/Then), feature file structure, Scenario Outline & Examples tables, tagging, step definitions", "Phase / Module": "Cucumber", "Learning Format": "Self-paced Video + Embedded Assignment", "Learning Outcome": "Learner can write business-readable Gherkin scenarios", "Video / Content (hrs)": "1", "Assignment / Hands-on (hrs)": "0.25", "Assignment(s) — realistic time incl. buffer": "A1 (15 min): Write a Gherkin scenario (Given/When/Then) for the ''auto-approved applicant'' happy path."}'),
	(400, 14, 48, NULL, 'Cucumber–Selenium Integration + Feature & Step-Def Lab', '{"Phase": "Phase 4 — Test Automation", "Topic": "Cucumber–Selenium Integration + Feature & Step-Def Lab", "Sub-Topic": "Tying Cucumber step definitions to Selenium automation", "Phase / Module": "Cucumber", "Learning Format": "Self-paced Video + Embedded Assignments", "Learning Outcome": "Learner can build and execute a working, multi-scenario BDD automation suite", "Artefact(s) Produced": "Feature files + step definitions + execution report", "Video / Content (hrs)": "1", "Assignment / Hands-on (hrs)": "1", "Assignment(s) — realistic time incl. buffer": "A1 (10 min): Write a Gherkin scenario for the ''missing mandatory field'' validation case.\nA2 (10 min): Write a Gherkin scenario for the ''ineligible applicant rejection'' case.\nA3 (20 min): Implement step definitions wiring all 3 scenarios to the existing Selenium POM classes.\nA4 (15 min): Execute all 3 scenarios against the sandbox app and confirm pass/fail status per scenario."}'),
	(401, 14, 49, NULL, 'Knowledge Check', '{"Phase": "Phase 4 — Test Automation", "Topic": "Knowledge Check", "Sub-Topic": "Auto-graded execution-based assessment", "Phase / Module": "Cucumber", "Learning Format": "Auto-graded Execution-based Assessment", "Learning Outcome": "Validated BDD/Cucumber automation competency", "Milestone / Gate": "MILESTONE 4 — Test Automation Gate: all Phase 4 checks passed -> unlocks Capstone", "Artefact(s) Produced": "Execution report", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "0.5", "Assignment(s) — realistic time incl. buffer": "Assessment scope: independent BDD scenario authored and executed against sandbox app"}'),
	(402, 14, 51, NULL, 'Digital Lending Platform — Integrated End-to-End Test Suite', '{"Phase": "Capstone", "Topic": "Digital Lending Platform — Integrated End-to-End Test Suite", "Sub-Topic": "Integrated end-to-end test of the Mphasis Digital Lending Platform sandbox application — a multi-step loan origination flow (Applicant Onboarding -> Eligibility Check -> Document Upload -> Approval Decision -> DB-confirmed disbursement status). Context: Mphasis is rolling out a new Digital Lending Platform for a banking client; as a QA engineering pod member, you build the foundational automated test suite ahead of UAT.", "Phase / Module": "Capstone Use Case", "Learning Format": "Embedded Assignments (full sandbox: app + DB + automation tooling)", "Learning Outcome": "Learner demonstrates integrated, independent application of all four core skill clusters (Java/JUnit, SQL, Selenium, Cucumber) on a single realistic BFSI scenario — the capstone readiness signal. Success criteria: all 3 Cucumber scenarios execute end-to-end without manual intervention, and the DB validation query returns the expected state for each.", "Artefact(s) Produced": "Capstone repo: Java classes + JUnit suite, POM-based Selenium scripts, Cucumber feature files + step definitions, SQL validation query, execution/test report", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "2", "Assignment(s) — realistic time incl. buffer": "A1 (30 min): Java + JUnit: extend ''LoanEligibilityChecker'' with a new ''calculateRiskScore()'' method combining CIBIL score, EMI ratio, and existing exposure; write a JUnit suite (min. 3 cases) covering edge cases such as a zero-income applicant and a maxed-out exposure applicant.\nA2 (30 min): Selenium (POM): automate the complete UI journey — applicant onboarding through to the approval decision screen — reusing the Page Object Model classes built in Phase 4.\nA3 (30 min): Cucumber (BDD): author a feature file with 3 end-to-end scenarios (auto-approved, manually-referred, rejected applicant) and wire step definitions to the Selenium automation.\nA4 (15 min): MySQL: write a validation query confirming the ''loan_applications'' table reflects the correct ''approval_status'' and ''disbursement_flag'' after each scenario executes, closing the UI-to-database loop."}'),
	(403, 14, 52, NULL, 'Consolidated Readiness Scoring', '{"Phase": "Capstone", "Topic": "Consolidated Readiness Scoring", "Sub-Topic": "Final baseline assessment & readiness report generation", "Phase / Module": "Final Readiness Baseline", "Learning Format": "Auto-graded Assessment + System Report", "Learning Outcome": "Generates a consolidated per-learner readiness score across all 10 skill nodes, used to gate/route entry into the full Fresher Training Program", "Milestone / Gate": "FINAL GATE — Program Completion: readiness score released to Fresher Training Program intake", "Artefact(s) Produced": "Readiness Baseline Report (PDF/dashboard export) — phase scores, skill-node scores, capstone outcome, overall readiness rating", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "1", "Assignment(s) — realistic time incl. buffer": "Assessment scope: consolidated scoring across all 10 skill nodes plus capstone outcome — no new problem statement, system-generated"}');


